        withLock(`${f.root}/deploy.lock`, () => Promise.resolve(undefined)),
        'lock held',
      );
    },
    f.root,
  );
  expect(effects).toBe(4);
  expect(f.execCalls.some((args) => args.at(11) === GROUP_PROGRAM)).toBe(true);
  expect(f.execCalls.some((args) => args.at(11) !== GROUP_PROGRAM)).toBe(true);
  const readbacks = await Promise.all(
