for (const fault of [
  'none',
  'created',
  'host-private',
  'solver-final',
  'source-final',
  'backend-final',
  'ingress-final',
  'incapable',
  'tuple',
  'image',
  'missing-image',
  'noop-remove',
  'interrupt-remove',
  'start',
  'service',
  'process',
  'socket',
  'mapping',
  'source-resumed',
  'source-mount-duplicate',
  'source-mount-field',
  'unrelated-mount-field',
  'new-participant',
  'source-record',
  'database',
  'intent-resumed',
  'process-drift',
  'policy-after-start',
  'config-json-private',
  'config-key-private',
  'config-utf8-private',
  'config-finalizer-private',
] as const) {
  test(`restoration coordinator starts only compatible solver after finalizers and leaves participants fenced: ${fault}`, async () => {
    const { restoreSolverAfterDependencyExclusion } = await import('./dependency-activation-owner');
    const { f, solver, prod, selectedDev, source, retained, events, runner } =
      await createSourceCompositionFixture(image, fault === 'created');
    await (await import('./edge-policy')).initializeOrdinaryEdgePolicy(f.root);
    let started = false;
    let observedCapabilities = false;
    let connected = false;
    let capturesAfterProbe = 0;
    let corrupted: Uint8Array | undefined;
    const sentinel = 'PRIVATE_REVIEW_CONFIG_SENTINEL';
    const corruptConfig = async () => {
      const original: unknown = JSON.parse(await readFile(`${f.root}/installed-2`, 'utf8'));
      if (typeof original !== 'object' || original === null || Array.isArray(original))
        throw new Error('fixture config unavailable');
      corrupted =
        fault === 'config-key-private'
          ? Buffer.from(JSON.stringify({ ...original, [sentinel]: 'secret' }))
          : fault === 'config-utf8-private'
            ? Buffer.concat([Buffer.from([255]), Buffer.from(sentinel)])
            : Buffer.from(`${sentinel}=secret`);
      await writeFile(`${f.root}/installed-2`, corrupted);
    };
    const restoredPhase = [
      'start',
      'service',
      'process',
      'socket',
      'mapping',
      'source-resumed',
      'source-mount-duplicate',
      'source-mount-field',
      'unrelated-mount-field',
      'new-participant',
      'source-record',
      'database',
      'intent-resumed',
      'process-drift',
    ].includes(fault);
    const monitoredDocker: RunDocker = async (args, signal) => {
      if (
        observedCapabilities &&
        fault === 'ingress-final' &&
        args[0] === 'exec' &&
        args.includes('wget')
      )
        return '{}';
      if (args[0] === 'rm' && fault === 'noop-remove') return '';
      const response = await runner(args, signal);
      if (args[0] === 'rm' && fault === 'interrupt-remove')
        throw new Error('coordinator interrupted after removal');
      return response;
    };
    const runHost = solver.ports.runHost;
    const ports = {
      ...solver.ports,
      captureFile: async (path: string, maximum: number, config = false) => {
        const observed = await solver.ports.captureFile(path, maximum, config);
        if (
          observedCapabilities &&
          fault === 'config-finalizer-private' &&
          ++capturesAfterProbe === 8
        )
          await corruptConfig();
        return observed;
      },
      observeCgroup: async (path: string, removedAllowed: boolean) => {
        const observed = await solver.ports.observeCgroup(path, removedAllowed);
        return started && observed !== null ? { ...observed, populated: true } : observed;
      },
      observeProcess: async (pid: number) => {
        const observed = await solver.ports.observeProcess(pid);
        return started && fault === 'process'
          ? { ...observed, cgroup: '/foreign' }
          : connected && fault === 'process-drift'
            ? { ...observed, startTime: '99999' }
            : observed;
      },
      connectSocket: async () => {
        if (!started || fault === 'socket') throw new Error('not listening');
        connected = true;
        if (fault === 'policy-after-start')
          await writeFile(
            `${f.root}/edge-policy.json`,
            JSON.stringify({
              format: 'dependency-edge-policy',
              version: 1,
              phase: 'ordinary',
              edgeState: f.root,
            }),
          );
        if (fault === 'intent-resumed') {
          const name = (await readdir(f.root)).find((name) =>
            name.endsWith('-solver-restore-intent.json'),
          );
          if (name === undefined) throw new Error('fixture restoration intent missing');
          const path = `${f.root}/${name}`;
          const bytes = await readFile(path);
          await rename(path, path + '.previous');
          await writeFile(path, bytes, { mode: 0o600 });
        }
        if (fault === 'source-resumed') source.State.Running = true;
        if (fault === 'source-mount-duplicate')
          source.Mounts[0].Destination = source.Mounts[1].Destination;
        if (fault === 'source-mount-field') Reflect.set(source.Mounts[0], 'Propagation', 'rshared');
        if (fault === 'unrelated-mount-field')
          Reflect.set(f.container.Mounts[0], 'Propagation', 'rshared');
        if (fault === 'new-participant') {
          const unrelated = structuredClone(f.container);
          unrelated.Id = '6'.repeat(64);
          unrelated.Name = '/unrelated';
          unrelated.Config.Image = 'alpine:1';
          unrelated.Config.Labels = {
            'com.docker.compose.service': 'unrelated',
            'com.docker.compose.project': 'other',
          };
          unrelated.Mounts = [];
          unrelated.NetworkSettings.Networks = {} as typeof unrelated.NetworkSettings.Networks;
          f.containers.push(unrelated);
        }
        if (fault === 'source-record')
          await writeFile(
            `${selectedDev.stateDir}/dependency-source-dev-intent.json`,
            (await readFile(`${selectedDev.stateDir}/dependency-source-dev-intent.json`, 'utf8')) +
              '\n',
          );
        if (fault === 'database') {
          await rename(`${f.root}/db/wbs.db`, `${f.root}/db/previous.db`);
          await writeFile(`${f.root}/db/wbs.db`, 'sqlite fixture');
        }
      },
      runDocker: async (args: string[], signal?: AbortSignal) => {
        if (args[0] === 'run') {
          observedCapabilities = true;
          if (
            fault === 'config-json-private' ||
            fault === 'config-key-private' ||
            fault === 'config-utf8-private'
          )
            await corruptConfig();
          if (fault === 'source-final') source.State.Running = true;
          if (fault === 'backend-final') f.container.State.Running = true;
          if (fault === 'tuple') await writeFile(`${f.root}/installed-1`, 'changed bundle');
          return JSON.stringify({
            protocol: 'wbs-dependency-runtime',
            version: 1,
            role: 'backend',
            semantics: fault === 'incapable' ? [] : ['cross-project-dependencies-v1'],
          });
        }
        if (args[0] === 'image' && observedCapabilities && fault === 'missing-image')
          throw new Error('configured image missing');
        if (
          args[0] === 'image' &&
          ((observedCapabilities && fault === 'image') || (started && fault === 'mapping'))
        )
          return `sha256:${'f'.repeat(64)}\n`;
        return solver.ports.runDocker(args, signal);
      },
      runHost: async (command: SolverHostCommand, signal?: AbortSignal) => {
        if (command.kind === 'show' && fault === 'host-private')
          return (await runHost(command, signal)).replace(
            'Environment=',
            'Environment=PRIVATE_HOST_SENTINEL=secret ',
          );
        if (command.kind === 'show' && observedCapabilities && fault === 'solver-final')
          throw new Error('final solver inspection');
        if (command.kind === 'start') {
          if (fault === 'start')
            throw new Error('coordinator interrupted after policy publication');
          await withLock(`${f.root}/solver-runtime.lock`, () => Promise.resolve());
          expect(
            (await (await import('./edge-policy')).captureEdgePolicy(f.root)).policy.phase,
          ).toBe('restoring');
          expect(source.State.Running).toBe(false);
          expect(f.container.State.Running).toBe(false);
          started = true;
          events.push('start');
          return '';
        }
        if (started && fault === 'service' && command.kind === 'show')
          return runHost(command, signal);
        if (started && command.kind === 'show')
          return (await runHost(command, signal))
            .replace('ActiveState=inactive', 'ActiveState=active')
            .replace('SubState=dead', 'SubState=running')
            .replace('MainPID=0', 'MainPID=123')
            .replace('InvocationID=\n', `InvocationID=${'a'.repeat(32)}\n`)
            .replace(
              'ControlGroup=\n',
              'ControlGroup=/user.slice/user-1000.slice/user@1000.service/app.slice/wbs-solver-supervisor.service\n',
            );
        if (command.kind === 'stop') events.push('solver');
        return runHost(command, signal);
      },
    };
    const restoring = restoreSolverAfterDependencyExclusion(
      { sha, layouts: [prod, selectedDev] },
      solver.pins,
      ports,
      monitoredDocker,
      performance.now() + 60000,
      namespaceFor(f.layout),
      f.exec,
      f.root,
    );
    if (fault !== 'none' && fault !== 'created') {
      const refusal = await refuses(
        restoring,
        fault === 'new-participant'
          ? 'restoration exact parked participants'
          : fault === 'source-record'
            ? 'restoration retained participant bytes'
            : '',
      );
      if (fault.startsWith('config-')) {
        expect(corrupted).toBeDefined();
        expect(inspectFailure(refusal, { depth: null })).not.toContain(sentinel);
        expect(refusal.message).toContain('solver installed configuration');
        if (corrupted === undefined) throw new Error('fixture corruption did not occur');
        expect(refusal.message).toContain(createHash('sha256').update(corrupted).digest('hex'));
        for (const directory of [f.root, selectedDev.stateDir])
          for (const name of await readdir(directory))
            if (name.endsWith('.json'))
              expect(await readFile(`${directory}/${name}`, 'utf8')).not.toContain(sentinel);
      }
      expect((await (await import('./edge-policy')).captureEdgePolicy(f.root)).policy.phase).toBe(
        restoredPhase ? 'restoring' : 'ordinary',
      );
      for (const name of await readdir(f.root))
        if (name.endsWith('.json'))
          expect(await readFile(`${f.root}/${name}`, 'utf8')).not.toContain(
            'PRIVATE_HOST_SENTINEL',
          );
      await refuses(assertNoEdgeOwner(f.root), 'admission closed');
      expect(
        (await readFile(prod.siteCaddyPath, 'utf8')).includes('WBS dependency maintenance'),
      ).toBe(true);
      return;
    }
    expect(await restoring).toEqual({
      state: 'solver-restored-participants-fenced',
      activation: 'not-performed',
      exposure: 'closed',
    });
    expect(started).toBe(true);
    expect(events.indexOf('removed')).toBeLessThan(events.indexOf('start'));
    expect(source.State.Running).toBe(false);
    expect(f.container.State.Running).toBe(false);
    expect(f.gateway.State.Running).toBe(false);
    expect(events.slice(0, 3)).toEqual(['ingress', 'solver', 'source']);
    expect(f.containers).not.toContain(retained);
    expect(f.namespaceCalls.some((call) => call.id === retained.Id)).toBe(false);
    for (const directory of [f.root, selectedDev.stateDir])
      for (const name of await readdir(directory))
        if (name.endsWith('.json'))
          expect(await readFile(`${directory}/${name}`, 'utf8')).not.toMatch(
            /COMPOSED_(?:PRIVATE|CADDY|ADAPTED)_SENTINEL/,
          );
  }, 20_000);
}

import { createHash, randomUUID } from 'node:crypto';

import {
  assertParkedBackendCohort,
  type BackendCohort as Cohort,
  type GatewayBinding,
  gatewayBinding,
  inspectBackendCohort as inspectCohort,
  inspectBackendCohortUnderOwner,
  parseBackendCohort as parseCohort,
  parseGatewayBinding,
} from './backend-cohort';
import { assertNoBackendFence } from './backend-fence';
import { type RunDocker, runDockerBefore } from './docker-deadline';
import { type DockerExec, runDockerExec } from './docker-exec';
import {
  assertDependencyOwner,
  type DependencyOwner,
  ownerDockerExec,
  ownerDockerHashed,
} from './edge-ownership';
import type { EnvLayout } from './env';
import { inspectGatewayFenceUnderLock } from './gateway-exclusion';
import { withLock } from './lock';
import {
  assertExcluded,
  assertRoot,
  assertSame,
  projectIdentities,
  publishRecord,
  readClosed,
  readRecord,
  readString,
} from './managed-cohort';
import { verifyContainerNamespace } from './mount-audit';
import type { SolverExclusion } from './solver-exclusion';
import type { SourceDevMember } from './source-dev-cohort';
import type { SourceDevExclusion } from './source-dev-exclusion';

const MARKER = '{"format":"dependency-backend-fence","version":1}\n';
const INTENT = 'dependency-backend-intent.json';
const COMPLETE = 'dependency-backend-complete.json';
const COLORS = ['blue', 'green'] as const;
const SHA = /^[a-f0-9]{40}$/;

interface Intent {
  format: 'dependency-backend-intent';
  version: 1;
  attempt: string;
  environment: string;
  root: string;
  network: string;
  sha: string;
  cohort: Cohort;
  gateway: GatewayBinding;
}
/** Historical receipt only. {@link inspectBackendFence} must freshly prove physical exclusion. */
export interface BackendCompletion {
  format: 'dependency-backend-complete';
  version: 1;
  attempt: string;
  intentSha256: string;
  cohort: Cohort;
  gateway: GatewayBinding;
}

function digestIntent(contents: string): string {
  return createHash('sha256').update(contents).digest('hex');
}

function serializeRecord(record: unknown): string {
  return `${JSON.stringify(record)}\n`;
}
function parseIntent(contents: string, layout: EnvLayout): Intent {
  const record = readClosed(JSON.parse(contents), [
    'format',
    'version',
    'attempt',
    'environment',
    'root',
    'network',
    'sha',
    'cohort',
    'gateway',
  ]);
  if (
    record['format'] !== 'dependency-backend-intent' ||
    record['version'] !== 1 ||
    record['environment'] !== layout.env ||
    record['root'] !== layout.root ||
    record['network'] !== layout.network ||
    !SHA.test(readString(record['sha'])) ||
    !/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(
      readString(record['attempt']),
    )
  )
    throw new Error('backend fence intent provenance is malformed or foreign');
  return {
    format: 'dependency-backend-intent',
    version: 1,
    attempt: readString(record['attempt']),
    environment: layout.env,
    root: layout.root,
    network: layout.network,
    sha: readString(record['sha']),
    cohort: parseCohort(record['cohort'], layout),
    gateway: parseGatewayBinding(record['gateway']),
  };
}
async function readRetainedRecord(path: string): Promise<string | null> {
  try {
    return await readRecord(path);
  } catch (cause) {
    if (cause instanceof Error && 'code' in cause && cause.code === 'ENOENT') return null;
    throw cause;
  }
}
async function readCompletion(
  layout: EnvLayout,
): Promise<{ intent: Intent; completion: BackendCompletion }> {
  const marker = await readRetainedRecord(`${layout.stateDir}/dependency-backend-fence.json`);
  const contents = await readRetainedRecord(`${layout.stateDir}/${INTENT}`);
  const completed = await readRetainedRecord(`${layout.stateDir}/${COMPLETE}`);
  if (marker === null && contents === null && completed === null)
    throw new Error('backend fence absent; no physical exclusion proof');
  if (completed !== null && (marker === null || contents === null))
    throw new Error(
      'backend fence corrupt orphan completion; retain evidence; attended recovery required',
    );
  if (marker === null)
    throw new Error(
      'backend fence corrupt orphan intent; retain evidence; attended recovery required',
    );
  assertSame(MARKER, marker, 'marker');
  if (contents === null)
    throw new Error(
      'backend fence interrupted before durable intent; retain marker; attended recovery required',
    );
  const intent = parseIntent(contents, layout);
  if (completed === null)
    throw new Error(
      'backend fence uncertain without completion; retain current Docker state; attended recovery required',
    );
  // Proof: extra-completion-field is refused even when the intent remains valid; no historical receipt grants exclusion.
  const record = readClosed(JSON.parse(completed), [
    'format',
    'version',
    'attempt',
    'intentSha256',
    'cohort',
    'gateway',
  ]);
  if (
    record['format'] !== 'dependency-backend-complete' ||
    record['version'] !== 1 ||
    record['attempt'] !== intent.attempt ||
    record['intentSha256'] !== digestIntent(contents)
  )
    throw new Error('backend fence completion is not bound to persisted intent');
  assertSame(intent.gateway, parseGatewayBinding(record['gateway']), 'completed gateway binding');
  const completion: BackendCompletion = {
    format: 'dependency-backend-complete',
    version: 1,
    attempt: intent.attempt,
    intentSha256: digestIntent(contents),
    cohort: parseCohort(record['cohort'], layout),
    gateway: parseGatewayBinding(record['gateway']),
  };
  assertSame(
    projectIdentities(intent.cohort),
    projectIdentities(completion.cohort),
    'completed identity',
  );
  assertExcluded(completion.cohort);
  return { intent, completion };
}

/**
 * Publish retained intent, disable restart and stop only the exact managed Compose blue/green IDs.
 * Owns deploy.lock; requires existing verified gateway exclusion. All Docker observations/effects share
 * one bounded budget. Any failure after publication retains evidence and current Docker state;
 * no cleanup, restart, activation, exposure or broad participant claim is authorized.
 * Existing backends without init/private PID/strict image/labels need attended preparation.
 * See docs/runbook-prod-deploy.md#managed-compose-backend-exclusion.
 */
export async function fenceBackends(
  layout: EnvLayout,
  sha: string,
  runDocker: RunDocker,
  totalMs = 60000,
  namespaceProof: typeof verifyContainerNamespace = verifyContainerNamespace,
): Promise<BackendCompletion> {
  if (!SHA.test(sha) || !Number.isFinite(totalMs) || totalMs <= 0)
    throw new Error('backend fence requires full git SHA and finite positive deadline');
  // Proof: holding the actual flock makes both backend executor/inspector refuse before Docker.
  return await withLock(`${layout.stateDir}/deploy.lock`, async () => {
    return await fenceBackendCore(
      layout,
      sha,
      runDocker,
      performance.now() + totalMs,
      namespaceProof,
    );
  });
}

/** Live owner path; takes no nested flock and grants no activation authority. */
export async function fenceBackendsUnderOwner(
  owner: DependencyOwner,
  layout: EnvLayout,
  sha: string,
  runDocker: RunDocker,
  deadline: number,
  namespaceProof: typeof verifyContainerNamespace = verifyContainerNamespace,
  execDocker: DockerExec = runDockerExec,
  source?: SourceDevExclusion,
  solver?: SolverExclusion,
): Promise<BackendCompletion> {
  await assertDependencyOwner(owner, layout, sha);
  // Proof: bypassing ownerDockerExec made composed acceptance reach scanner without nonce-bound durable intent (exit 1).
  const verifyOwnedNamespace: typeof verifyContainerNamespace = (
    container,
    destinations,
    databaseHostPath,
    image,
    docker,
    databasePath,
    bounds,
  ) =>
    namespaceProof(
      container,
      destinations,
      databaseHostPath,
      image,
      docker,
      databasePath,
      bounds,
      ownerDockerExec(owner, layout, execDocker),
    );
  return fenceBackendCore(
    layout,
    sha,
    ownerDockerHashed(owner, layout, runDocker),
    deadline,
    verifyOwnedNamespace,
    source === undefined ? undefined : { owner, exclusion: source, solver },
  );
}

async function fenceBackendCore(
  layout: EnvLayout,
  sha: string,
  runDocker: RunDocker,
  deadline: number,
  namespaceProof: typeof verifyContainerNamespace,
  source?: { owner: DependencyOwner; exclusion: SourceDevExclusion; solver?: SolverExclusion },
): Promise<BackendCompletion> {
  const observe = () =>
    source === undefined
      ? inspectCohort(layout, runDocker, deadline, gateway, namespaceProof)
      : inspectBackendCohortUnderOwner(
          source.owner,
          layout,
          source.exclusion,
          runDocker,
          deadline,
          gateway,
          namespaceProof,
          source.solver,
        );
  await assertRoot(layout);
  await assertNoBackendFence(layout.stateDir);
  // Proof: missing-gateway and resumed-gateway production invocations refuse before backend publication/effects.
  await inspectGatewayFenceUnderLock(layout, runDocker, deadline);
  const gateway = await gatewayBinding(layout);
  const cohort = await observe();
  try {
    await publishRecord(`${layout.stateDir}/dependency-backend-fence.json`, MARKER);
    const intent: Intent = {
      format: 'dependency-backend-intent',
      version: 1,
      attempt: randomUUID(),
      environment: layout.env,
      root: layout.root,
      network: layout.network,
      sha,
      cohort,
      gateway,
    };
    const contents = serializeRecord(intent);
    // Proof: deleting this publication fails every-backend-effect-before-durable-intent (exit 1).
    await publishRecord(`${layout.stateDir}/${INTENT}`, contents);
    assertSame(cohort, await observe(), 'pre-effect cohort');
    for (const color of COLORS) {
      const backend = cohort[color];
      if (backend === null) continue;
      // Proof: suppressing update fails both-colours success at independent policy readback (exit 1).
      await runDockerBefore(['update', '--restart=no', backend.id], runDocker, deadline);
      const observed = await observe();
      const expected: Cohort = structuredClone(cohort);
      const updated = expected[color];
      if (updated === null) throw new Error('backend fence lost known cohort member');
      updated.restartPolicy = { name: 'no', maximumRetryCount: 0 };
      // Proof: deleting this readback admits stop after skipped restart; skipped-restart negative fails (exit 1).
      assertSame(expected, observed, 'restart update readback');
      cohort[color] = observed[color];
    }
    for (const color of COLORS) {
      const backend = cohort[color];
      if (backend === null) continue;
      // Proof: suppressing stop fails both-colours success at fresh process/PID exclusion (exit 1).
      await runDockerBefore(['stop', '--time', '10', backend.id], runDocker, deadline);
      const observed = await observe();
      assertSame(projectIdentities(cohort), projectIdentities(observed), 'stop identity readback');
      const stopped = observed[color];
      if (stopped === null) throw new Error('backend fence lost stopped member');
      assertExcluded({ blue: stopped, green: null });
      for (const other of COLORS)
        if (other !== color) assertSame(cohort[other], observed[other], 'unaffected member');
      cohort[color] = stopped;
    }
    const stopped = await observe();
    assertSame(cohort, stopped, 'fresh stopped cohort');
    assertExcluded(stopped);
    const completion: BackendCompletion = {
      format: 'dependency-backend-complete',
      version: 1,
      attempt: intent.attempt,
      intentSha256: digestIntent(contents),
      cohort: stopped,
      gateway,
    };
    await publishRecord(`${layout.stateDir}/${COMPLETE}`, serializeRecord(completion));
    const retained = await readCompletion(layout);
    assertSame(completion, retained.completion, 'completion readback');
    // Proof: substituting historical stopped state admits completion-drift; its production-path negative fails (exit 1).
    const final = await observe();
    assertSame(stopped, final, 'final current cohort');
    assertExcluded(final);
    return completion;
  } catch (cause) {
    throw new Error(
      `backend fence failed after publication; retain all dependency-backend records and current Docker state; explicit attended recovery required; no restart or automatic cleanup: ${cause instanceof Error ? cause.message : String(cause)}`,
      { cause },
    );
  }
}

/** Read-only lock-owned proof; historical completion alone never establishes present exclusion. */
export async function inspectBackendFence(
  layout: EnvLayout,
  runDocker: RunDocker,
  namespaceProof: typeof verifyContainerNamespace = verifyContainerNamespace,
): Promise<BackendCompletion> {
  // Proof: holding the actual flock makes both backend executor/inspector refuse before Docker.
  return await withLock(`${layout.stateDir}/deploy.lock`, async () => {
    return await inspectBackendFenceUnderLock(
      layout,
      runDocker,
      performance.now() + 60000,
      namespaceProof,
    );
  });
}

/**
 * Freshly inspect retained backend/gateway exclusion while the caller holds this
 * layout's deploy.lock. Shares the owner's total Docker deadline; never acquires
 * another lock and establishes no completeness beyond this managed DB cohort.
 */
export async function inspectBackendFenceUnderLock(
  layout: EnvLayout,
  runDocker: RunDocker,
  deadline: number = performance.now() + 60000,
  namespaceProof: typeof verifyContainerNamespace = verifyContainerNamespace,
): Promise<BackendCompletion> {
  await assertRoot(layout);
  const { completion, intent } = await readCompletion(layout);
  const gateway = intent.gateway;
  const observed = await inspectCohort(layout, runDocker, deadline, gateway, namespaceProof);
  // Proof: deleting current-cohort equality admits a replaced main DB inode; replaced-main-file negative fails (exit 1).
  assertSame(completion.cohort, observed, 'current completed cohort');
  assertExcluded(observed);
  return completion;
}

/** Fresh live owner proof with the same source context at every backend inventory observation. */
export async function inspectBackendFenceUnderOwner(
  owner: DependencyOwner,
  layout: EnvLayout,
  sha: string,
  runDocker: RunDocker,
  deadline: number,
  source: SourceDevExclusion,
  namespaceProof: typeof verifyContainerNamespace = verifyContainerNamespace,
  execDocker: DockerExec = runDockerExec,
  solver?: SolverExclusion,
): Promise<BackendCompletion> {
  await assertDependencyOwner(owner, layout, sha);
  await assertRoot(layout);
  const { completion, intent } = await readCompletion(layout);
  const verifyOwnedNamespace: typeof verifyContainerNamespace = (
    container,
    destinations,
    databaseHostPath,
    image,
    docker,
    databasePath,
    bounds,
  ) =>
    namespaceProof(
      container,
      destinations,
      databaseHostPath,
      image,
      docker,
      databasePath,
      bounds,
      ownerDockerExec(owner, layout, execDocker),
    );
  const observed = await inspectBackendCohortUnderOwner(
    owner,
    layout,
    source,
    ownerDockerHashed(owner, layout, runDocker),
    deadline,
    intent.gateway,
    verifyOwnedNamespace,
    solver,
  );
  assertSame(completion.cohort, observed, 'current completed owner cohort');
  assertExcluded(observed);
  return completion;
}

/** Fresh monitoring of a retained parked backend and DB family; supplies no storage-admission capability. */
export async function assertParkedBackendFenceUnderOwner(
  owner: DependencyOwner,
  layout: EnvLayout,
  sha: string,
  runDocker: RunDocker,
  deadline: number,
  source?: { layout: EnvLayout; member: SourceDevMember },
): Promise<void> {
  await assertDependencyOwner(owner, layout, sha);
  await assertRoot(layout);
  const { completion, intent } = await readCompletion(layout);
  await assertParkedBackendCohort(
    layout,
    completion.cohort,
    intent.gateway,
    ownerDockerHashed(owner, layout, runDocker),
    deadline,
    source,
  );
  await assertDependencyOwner(owner, layout, sha);
}

import type { Stats } from 'node:fs';
import { lstat, opendir, readFile, stat } from 'node:fs/promises';

/**
 * Refuses admission while a deploy-owned dependency backend fence is retained.
 * The closed v1 marker is exactly `{format: 'dependency-backend-fence', version: 1}`.
 * Presence is a conservative barrier, never evidence that any backend is excluded.
 * This reader neither creates nor clears intent; the deploy lock must cover publication
 * and ordinary admission; the explicit managed exclusion lifecycle owns that transition.
 * Missing/unreadable trusted state and malformed, unreadable or symlink markers throw.
 * Directory readability is established using actual process access, including ACLs/privileges,
 * rather than inferring access from mode bits. Marker absence is checked without following links.
 */
export async function assertNoBackendFence(root: string): Promise<void> {
  try {
    if (!(await stat(root)).isDirectory()) throw new Error('state root is not a directory');
    const directory = await opendir(root);
    try {
      await directory.read();
    } finally {
      await directory.close();
    }
  } catch (cause) {
    throw new Error(`cannot inspect backend fence state directory ${root}; admission refused`, {
      cause,
    });
  }
  // Companion records without a marker are corrupt retained attempts, never clean admission.
  // Proof: retained marker/intent/completion production-path negatives all refuse before ordinary swap effects; orphan records never imply clean admission.
  for (const companion of ['dependency-backend-intent.json', 'dependency-backend-complete.json']) {
    const companionPath = `${root}/${companion}`;
    try {
      await lstat(companionPath);
    } catch (cause) {
      if (cause instanceof Error && 'code' in cause && cause.code === 'ENOENT') continue;
      throw new Error(
        `cannot inspect backend fence companion ${companionPath}; admission refused`,
        { cause },
      );
    }
    throw new Error(
      `retained backend fence companion ${companionPath}; admission refused; explicit recovery required`,
    );
  }
  const path = `${root}/dependency-backend-fence.json`;
  let identity: Stats;
  try {
    identity = await lstat(path);
  } catch (cause) {
    if (cause instanceof Error && 'code' in cause && cause.code === 'ENOENT') return;
    throw new Error(`cannot inspect backend fence ${path}; admission refused`, { cause });
  }
  if (!identity.isFile())
    throw new Error(`backend fence ${path} is not a regular file; admission refused`);
  let contents: string;
  try {
    contents = await readFile(path, 'utf8');
  } catch (cause) {
    throw new Error(`cannot read backend fence ${path}; admission refused`, { cause });
  }
  let marker: unknown;
  try {
    marker = JSON.parse(contents);
  } catch (cause) {
    throw new Error(`malformed backend fence ${path}; admission refused`, { cause });
  }
  if (
    marker === null ||
    typeof marker !== 'object' ||
    Array.isArray(marker) ||
    Object.keys(marker).length !== 2 ||
    Reflect.get(marker, 'format') !== 'dependency-backend-fence' ||
    Reflect.get(marker, 'version') !== 1
  )
    throw new Error(`malformed backend fence ${path}; admission refused`);
  throw new Error(`retained backend fence ${path}; admission refused; explicit recovery required`);
}

