/**
 * First owner slice only. Retains all ownership and fence records on every exit.
 * No complete participant proof, storage activation, restoration or exposure is produced.
 */
export async function excludeManagedDependencies(
  plan: DependencyOwnerPlan,
  runDocker: RunDocker,
  namespaceProof: typeof verifyContainerNamespace = verifyContainerNamespace,
  directory = edgeStateDirectory(),
  execDocker: DockerExec = runDockerExec,
) {
  return excludeDependencies('managed', plan, runDocker, namespaceProof, directory, execDocker);
}

async function excludeDependencies(
  mode: 'managed' | 'ingress-managed',
  plan: DependencyOwnerPlan,
  runDocker: RunDocker,
  namespaceProof: typeof verifyContainerNamespace,
  directory: string,
  execDocker: DockerExec,
) {
  plan = structuredClone(plan);
  return withDependencyOwner(
    plan,
    async (owner) => {
      const deadline = performance.now() + 60000;
      if (mode === 'ingress-managed')
        await fenceDependencyIngress(owner, plan.layouts, runDocker, deadline);
      for (const layout of [...plan.layouts].sort((left, right) =>
        left.env === right.env ? 0 : left.env === 'prod' ? -1 : 1,
      )) {
        await fenceGatewaysUnderOwner(owner, layout, plan.sha, runDocker, deadline);
        await fenceBackendsUnderOwner(
          owner,
          layout,
          plan.sha,
          runDocker,
          deadline,
          namespaceProof,
          execDocker,
        );
      }
      if (mode === 'ingress-managed')
        await inspectDependencyIngress(owner, plan.layouts, runDocker, deadline);
      return {
        state: 'managed-excluded' as const,
        activation: 'blocked' as const,
        unresolved: [
          'installed-writer-adoption',
          'ingress',
          'MCP',
          'solver',
          'replay-background',
          'restart-authority',
          'atomic-activation',
          'compatible-restoration',
        ],
      };
    },
    directory,
  );
}

/** Explicit ingress-inclusive slice; the ordinary managed-only entrypoint retains its behavior. */
export async function excludeIngressAndManagedDependencies(
  plan: DependencyOwnerPlan,
  runDocker: RunDocker,
) {
  return excludeDependencies(
    'ingress-managed',
    plan,
    runDocker,
    verifyContainerNamespace,
    edgeStateDirectory(),
    runDockerExec,
  );
}

/** Explicit callable solver interval; callers must enclose all remaining protected work. */
export async function excludeSolverUnderDependencyOwner<T>(
  plan: DependencyOwnerPlan,
  pins: SolverPins,
  ports: SolverPorts,
  deadline: number,
  action: (owner: DependencyOwner) => Promise<T>,
  directory = SOLVER_EDGE_STATE,
): Promise<{ state: 'solver-drained'; activation: 'blocked'; value: T }> {
  plan = structuredClone(plan);
  if (directory !== ports.edgeState)
    throw new Error('solver owner and adapter state namespace differ');
  const prod = plan.layouts.find((layout) => layout.env === 'prod');
  const dev = plan.layouts.find((layout) => layout.env === 'dev');
  if (prod === undefined || dev === undefined)
    throw new Error('solver owner requires prod and dev');
  return withDependencyOwner(
    plan,
    async (owner) => {
      const value = await withSolverDrainUnderOwner(
        owner,
        { prod, dev },
        pins,
        ports,
        deadline,
        () => action(owner),
      );
      return { state: 'solver-drained', activation: 'blocked', value };
    },
    directory,
  );
}

/**
 * Explicit whole-source dev composition. Holds ingress and solver/source exclusion throughout
 * prod managed fences, awaited continuation and final readbacks. Returns no activation grant;
 * unsupported installed authorities or retained mounted attempts still refuse ordinary audits.
 */
export async function excludeSourceAndManagedDependencies<T>(
  plan: DependencyOwnerPlan,
  pins: SolverPins,
  ports: SolverPorts,
  runDocker: RunDocker,
  deadline: number,
  action: (owner: DependencyOwner, source: SourceDevExclusion) => Promise<T>,
  namespaceProof: typeof verifyContainerNamespace = verifyContainerNamespace,
  execDocker: DockerExec = runDockerExec,
  directory = SOLVER_EDGE_STATE,
): Promise<{ state: 'source-managed-excluded'; activation: 'blocked'; value: T }> {
  plan = structuredClone(plan);
  const prod = plan.layouts.find((layout) => layout.env === 'prod');
  const dev = plan.layouts.find((layout) => layout.env === 'dev');
  if (
    prod === undefined ||
    dev === undefined ||
    plan.layouts.length !== 2 ||
    directory !== ports.edgeState
  )
    throw new Error('source composition requires exact joint prod/dev owner and solver namespace');
  return withDependencyOwner(
    plan,
    async (owner) => ({
      state: 'source-managed-excluded',
      activation: 'blocked',
      value: await excludeSourceAndManagedUnderOwner(
        owner,
        plan,
        { prod, dev },
        pins,
        ports,
        runDocker,
        deadline,
        (authority, source) => action(authority, source),
        namespaceProof,
        execDocker,
      ),
    }),
    directory,
  );
}

/** @internal */
export async function excludeSourceAndManagedUnderOwner<T>(
  owner: DependencyOwner,
  plan: DependencyOwnerPlan,
  layouts: SolverLayouts,
  pins: SolverPins,
  ports: SolverPorts,
  runDocker: RunDocker,
  deadline: number,
  action: (
    owner: DependencyOwner,
    source: SourceDevExclusion,
    solver: SolverExclusion,
  ) => Promise<T>,
  namespaceProof: typeof verifyContainerNamespace,
  execDocker: DockerExec,
  expectedServing?: DependencyServingSelection,
): Promise<T> {
  const { prod, dev } = layouts;
  await fenceDependencyIngress(owner, [prod, dev], runDocker, deadline, expectedServing);
  const value = await withSolverDrainUnderOwner(
    owner,
    { prod, dev },
    pins,
    ports,
    deadline,
    (solver) =>
      withSourceDevExcluded(owner, { prod, dev }, plan.sha, runDocker, deadline, async (source) => {
        await fenceGatewaysUnderOwner(owner, prod, plan.sha, runDocker, deadline);
        await fenceBackendsUnderOwner(
          owner,
          prod,
          plan.sha,
          runDocker,
          deadline,
          namespaceProof,
          execDocker,
          source,
          solver,
        );
        const inspect = async () => {
          await inspectDependencyIngress(owner, [prod, dev], runDocker, deadline);
          // Proof: replacing hashed Docker with raw retention leaked the composed environment sentinel; combined coordinator test failed.
          await inspectGatewayFenceUnderLock(
            prod,
            ownerDockerHashed(owner, prod, runDocker),
            deadline,
          );
          await inspectBackendFenceUnderOwner(
            owner,
            prod,
            plan.sha,
            runDocker,
            deadline,
            source,
            namespaceProof,
            execDocker,
            solver,
          );
          await inspectSourceDevExclusion(owner, source);
        };
        await inspect();
        try {
          return await action(owner, source, solver);
        } finally {
          await inspect();
        }
      }),
  );
  return value;
}

/** Restores only the independently pinned compatible supervisor; participants and every public exposure remain fenced. */
export async function restoreSolverAfterDependencyExclusion(
  plan: DependencyOwnerPlan,
  pins: SolverPins,
  ports: SolverRestorePorts,
  runDocker: RunDocker,
  deadline: number,
  namespaceProof: typeof verifyContainerNamespace = verifyContainerNamespace,
  execDocker: DockerExec = runDockerExec,
  directory = SOLVER_EDGE_STATE,
): Promise<{
  state: 'solver-restored-participants-fenced';
  activation: 'not-performed';
  exposure: 'closed';
}> {
  plan = structuredClone(plan);
  pins = decodeSolverPins(pins);
  const prod = plan.layouts.find((layout) => layout.env === 'prod');
  const dev = plan.layouts.find((layout) => layout.env === 'dev');
  if (
    prod === undefined ||
    dev === undefined ||
    plan.layouts.length !== 2 ||
    directory !== ports.edgeState
  )
    throw new Error('solver restoration requires exact joint prod/dev owner and solver namespace');
  const layouts = { prod, dev };
  return withDependencyOwner(
    plan,
    async (owner) => {
      const original = await captureEdgePolicy(directory);
      decodeOrdinaryEdgePolicy(original.policy, directory);
      const prepared = await excludeSourceAndManagedUnderOwner(
        owner,
        plan,
        layouts,
        pins,
        ports,
        runDocker,
        deadline,
        async (authority, source, solver) => {
          const parked = await captureParkedDependencies(
            authority,
            layouts,
            plan.sha,
            source,
            solver,
            runDocker,
            deadline,
          );
          const intent = await retainCompatibleSolverIntent(
            authority,
            layouts,
            pins,
            ports,
            deadline,
          );
          const installed = await captureSolverTuple(pins, ports.captureFile);
          return { parked, intent, installed };
        },
        namespaceProof,
        execDocker,
      );
      await restoreSolverUnderOwner(owner, layouts, pins, ports, deadline, original, prepared);
      return {
        state: 'solver-restored-participants-fenced',
        activation: 'not-performed',
        exposure: 'closed',
      };
    },
    directory,
  );
}

import { lstat, readdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

import { Database } from 'bun:sqlite';
import { afterEach, expect, spyOn, test } from 'bun:test';

import { participantActivationFixture } from '../fixtures/dependency-participant-restoration';
import { roots } from '../fixtures/source-startup';
import {
  activateCompleteDependenciesUnderOwner,
  prepareActivatedParticipantsUnderOwner,
  releasePreparedDependencyActivation,
} from './complete-dependency-exclusion';
import * as ownership from './edge-ownership';
import { readFields } from './managed-cohort';

afterEach(async () => {
  for (const root of roots.splice(0)) await rm(root, { recursive: true, force: true });
  delete process.env['WBS_EDGE_STATE'];
});

for (const boundary of ['capture', 'fenced-only', 'preparation'] as const)
  test(`original numbered publication refuses same-byte replacement at ${boundary} return boundary`, async () => {
    const fixture = await participantActivationFixture();
    process.env['WBS_EDGE_STATE'] = fixture.root;
    const policy = await readFile(join(fixture.root, 'edge-policy.json'), 'utf8');
    const retain = ownership.retainActivationRecord;
    let injected = false;
    let expectedReceipt: string | undefined;
    const publication = spyOn(ownership, 'retainActivationRecord').mockImplementation(
      async (owner, layouts, label, record) => {
        const original = await retain(owner, layouts, label, record);
        if (label === 'committed') expectedReceipt = JSON.stringify(readFields(record)['receipt']);
        if (label === (boundary === 'capture' ? 'capture' : 'fenced-complete')) {
          const before = await lstat(original.path, { bigint: true });
          await rename(original.path, original.path + '.PRIVATE_original');
          await writeFile(original.path, original.contents, { flag: 'wx', mode: 0o600 });
          const after = await lstat(original.path, { bigint: true });
          expect(`${String(after.dev)}:${String(after.ino)}`).not.toBe(
            `${String(before.dev)}:${String(before.ino)}`,
          );
          expect(await readFile(original.path, 'utf8')).toBe(original.contents);
          injected = true;
        }
        return original;
      },
    );
    let refusal: unknown;
    try {
      await ownership.withDependencyOwner(
        fixture.request.owner,
        async (owner) => {
          try {
            const parameters = [
              owner,
              fixture.request,
              fixture.layouts,
              performance.now() + 300000,
              fixture.root,
              fixture.ports,
            ] as const;
            if (boundary === 'preparation') {
              const prepared = await prepareActivatedParticipantsUnderOwner(...parameters);
              releasePreparedDependencyActivation(owner, prepared);
            } else {
              await activateCompleteDependenciesUnderOwner(...parameters);
            }
          } catch (cause) {
            refusal = cause;
          }
        },
        fixture.root,
      );
    } finally {
      publication.mockRestore();
    }
    expect(injected).toBe(true);
    expect(refusal).toBeInstanceOf(Error);
    expect(String(refusal)).toContain(
      boundary === 'capture' ? 'stage=capture;' : 'stage=exclusion-or-finalizer;',
    );
    for (const [path, enabled] of [
      [fixture.prodPath, boundary !== 'capture'],
      [fixture.devPath, false],
    ] as const) {
      const database = new Database(path, { create: false, readonly: true });
      try {
        expect(
          database.query('SELECT state FROM cross_project_dependency_activation').all(),
        ).toEqual([{ state: enabled ? 'ENABLED' : 'DISABLED' }]);
        expect(
          database.query('SELECT * FROM cross_project_dependency_activation_receipt').all().length,
        ).toBe(enabled ? 1 : 0);
        if (enabled) {
          expect(expectedReceipt).toBeDefined();
          expect(
            database.query('SELECT receipt FROM cross_project_dependency_activation_receipt').all(),
          ).toEqual([{ receipt: expectedReceipt }]);
        }
      } finally {
        database.close();
      }
    }
    const names = await readdir(fixture.root);
    if (boundary === 'capture') {
      expect(
        names.some(
          (name) =>
            name.includes('activation-intent') || name.includes('activation-fenced-complete'),
        ),
      ).toBe(false);
      const attempt = names.find((name) => name.startsWith('dependency-activation-'));
      if (attempt === undefined) throw new Error('actual storage attempt absent');
      expect(
        (await readdir(join(fixture.root, attempt))).some((name) =>
          name.endsWith('.before.sqlite'),
        ),
      ).toBe(false);
    }
    expect(await readFile(join(fixture.root, 'edge-policy.json'), 'utf8')).toBe(policy);
    expect(fixture.source.State.Running).toBe(false);
    expect(fixture.backend.State.Running).toBe(false);
    expect(fixture.gateway.State.Running).toBe(false);
    expect(fixture.commands.some((args) => ['start', 'restart', 'rm'].includes(args[0]))).toBe(
      false,
    );
  }, 300000);

import { chmod, mkdir, readFile, writeFile } from 'node:fs/promises';
import { basename } from 'node:path';

import { scratchSync } from '@tools/test-scratch';
import { expect, spyOn, test } from 'bun:test';

import {
  inspectDependencyOwnerPublication,
  retainActivationRecord,
  withDependencyOwner,
} from './edge-ownership';
import { captureEdgeRecord } from './edge-policy';
import { envLayout } from './env';
import { readFields } from './managed-cohort';
import * as migrationCapture from './migration-capture-file';

test('retains activation evidence under exact live joint owner and refuses copied or expired authority', async () => {
  const root = scratchSync('activation-record-');
  await writeFile(`${root}/edge.lock`, '');
  const layouts = {
    prod: { ...envLayout('prod'), root: `${root}/prod`, stateDir: `${root}/prod` },
    dev: { ...envLayout('dev'), root: `${root}/dev`, stateDir: `${root}/dev` },
  };
  await mkdir(layouts.prod.root);
  await mkdir(layouts.dev.root);
  const plan = { sha: 'a'.repeat(40), layouts: [layouts.prod, layouts.dev] };
  const owner = await withDependencyOwner(
    plan,
    async (owner) => {
      const publication = await inspectDependencyOwnerPublication(owner, layouts);
      expect(publication.plan).toEqual(plan);
      const record = await retainActivationRecord(owner, layouts, 'fenced-complete', {
        format: 'dependency-activation-fenced-complete',
        version: 1,
        activated: [],
        exposure: 'closed',
        controllers: 'fenced',
      });
      expect(record).toEqual(await captureEdgeRecord(root, basename(record.path), 65536));
      expect(Object.keys(record).sort()).toEqual(
        ['path', 'device', 'inode', 'parentDevice', 'parentInode', 'mode', 'contents'].sort(),
      );
      const retained: unknown = JSON.parse(await readFile(record.path, 'utf8'));
      expect(readFields(retained)['owner']).toBe(
        await readFile(`${root}/edge-owner.pending`, 'utf8'),
      );
      expect(inspectDependencyOwnerPublication({ ...owner }, layouts)).rejects.toThrow('live');
      await writeFile(
        `${root}/edge-owner.pending`,
        JSON.stringify({ ...publication, attempt: 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb' }) + '\n',
      );
      expect(inspectDependencyOwnerPublication(owner, layouts)).rejects.toThrow(
        'publication changed',
      );
      return owner;
    },
    root,
  );
  expect(inspectDependencyOwnerPublication(owner, layouts)).rejects.toThrow('live');
});

test('activation record readback admits every closed label and rejects sibling paths', async () => {
  const directory = scratchSync('activation-record-readback-');
  for (const label of [
    'participants',
    'capture',
    'backup',
    'intent',
    'committed',
    'fenced-complete',
    'participant-restore-intent',
    'participant-start-intent',
    'participant-ready',
    'participant-policy-intent',
    'participants-restored',
  ]) {
    const name = `edge-owner-000001-activation-${label}.json`;
    await writeFile(`${directory}/${name}`, '{}\n', { mode: 0o600 });
    expect((await captureEdgeRecord(directory, name, 65536)).contents).toBe('{}\n');
  }
  for (const name of [
    'edge-owner-000001-activation-unknown.json',
    '../edge-owner-000001-activation-intent.json',
    'edge-owner-1-activation-intent.json',
  ]) {
    expect(captureEdgeRecord(directory, name, 65536)).rejects.toThrow('unsupported edge record');
  }
});

for (const fault of [
  'directory-sync',
  'private-readback',
  'public-readback',
  'exclusive-name',
] as const)
  test(`actual owner activation publication refuses ${fault}`, async () => {
    const root = scratchSync('activation-publication-fault-');
    await writeFile(`${root}/edge.lock`, '');
    const layouts = {
      prod: { ...envLayout('prod'), root: `${root}/prod`, stateDir: `${root}/prod` },
      dev: { ...envLayout('dev'), root: `${root}/dev`, stateDir: `${root}/dev` },
    };
    await mkdir(layouts.prod.root);
    await mkdir(layouts.dev.root);
    const write = migrationCapture.writeNewMigrationCapture;
    let injected = false;
    const publication = spyOn(migrationCapture, 'writeNewMigrationCapture').mockImplementation(
      async (path, contents, sync) => {
        if (!path.includes('-activation-fenced-complete.json')) return write(path, contents, sync);
        injected = true;
        if (fault === 'directory-sync')
          return write(path, contents, () =>
            Promise.reject(new Error('injected actual publication directory sync failure')),
          );
        if (fault === 'exclusive-name')
          await writeFile(path, 'original evidence\n', { mode: 0o600 });
        await write(path, contents, sync);
        if (fault === 'private-readback') await chmod(path, 0o000);
        if (fault === 'public-readback') await chmod(path, 0o644);
      },
    );
    try {
      await withDependencyOwner(
        { sha: 'a'.repeat(40), layouts: [layouts.prod, layouts.dev] },
        (owner) => {
          expect(
            retainActivationRecord(owner, layouts, 'fenced-complete', {
              format: 'dependency-activation-fenced-complete',
              version: 1,
              activated: [],
              exposure: 'closed',
              controllers: 'fenced',
            }),
          ).rejects.toThrow();
          return Promise.resolve();
        },
        root,
      );
    } finally {
      publication.mockRestore();
    }
    expect(injected).toBe(true);
    if (fault === 'exclusive-name')
      expect(
        await readFile(`${root}/edge-owner-000001-activation-fenced-complete.json`, 'utf8'),
      ).toBe('original evidence\n');
  });

import type { DependencyActivationReceipt } from '@wbs/contracts/dependency-runtime';

import type { DatabaseIdentity } from './backend-cohort';
import type { DependencyCapabilityObservation } from './dependency-capability';
import type { DependencyParticipantRole } from './dependency-participant-preparation';
import type { ParticipantRestartPolicy } from './dependency-participant-transition';
import type { EnvName } from './env';
import type { SolverPins } from './solver-host';
import type { SourceDevInputObservation } from './source-dev-inputs';

export interface ActivationRecordReference {
  readonly name: string;
  readonly sha256: string;
}
interface ReceiptEntry {
  readonly environment: EnvName;
  readonly receipt: DependencyActivationReceipt;
}
interface ParticipantImage {
  readonly id: string;
  readonly image: string;
  readonly imageId: string;
}
/** Hash projections only. Source/configuration bodies and collector payloads never enter durable participant evidence. */
export interface CompleteDependencyParticipants {
  readonly format: 'complete-dependency-participants';
  readonly version: 1;
  readonly operation: 'activate-installed-dormant';
  readonly sourceSha: string;
  readonly ownerPublicationSha256: string;
  readonly selected: {
    readonly backend: ParticipantImage;
    readonly gateway: ParticipantImage;
    readonly source: {
      readonly id: string;
      readonly runtimeReference: string;
      readonly runtimeImageId: string;
      readonly manifestSha256: string;
      readonly environmentSha256: string;
    };
  };
  readonly capabilities: {
    readonly backendCandidate: DependencyCapabilityObservation;
    readonly backendRetained: DependencyCapabilityObservation;
    readonly gateway: DependencyCapabilityObservation;
    readonly source: SourceDevInputObservation['capabilities'];
  };
  readonly authorities: {
    readonly writerManifestSha256: string;
    readonly launchConfigurationSha256: string;
    readonly hostMachineIdSha256: string;
    readonly bootId: string;
    readonly filesSha256: string;
  };
  readonly solver: {
    readonly pins: SolverPins;
    readonly restorationIntent: ActivationRecordReference;
  };
  readonly databases: readonly (DatabaseIdentity & { readonly environment: EnvName })[];
  readonly fences: {
    readonly ingressSha256: string;
    readonly sourceSha256: string;
    readonly backendSha256: string;
    readonly gatewaySha256: string;
    readonly solverSha256: string;
  };
  readonly migrationManifestSha256: string;
}
/** Closed records produced only by the activation coordinator and its direct storage shell. */
export interface ActivationRecordByLabel {
  readonly participants: CompleteDependencyParticipants;
  readonly capture: {
    readonly format: 'dependency-activation-capture';
    readonly version: 1;
    readonly environment: EnvName;
    readonly databaseIdentity: string;
    readonly capture: ActivationRecordReference;
  };
  readonly backup: {
    readonly format: 'dependency-activation-backup';
    readonly version: 1;
    readonly environment: EnvName;
    readonly databaseIdentity: string;
    readonly snapshot: ActivationRecordReference & {
      readonly bytes: number;
      readonly migrations: readonly string[];
    };
    readonly captureSha256: string;
  };
  readonly intent: {
    readonly format: 'dependency-activation-intent';
    readonly version: 1;
    readonly environment: EnvName;
    readonly receipt: DependencyActivationReceipt;
    readonly participantRecord: ActivationRecordReference;
    readonly capture: ActivationRecordReference;
    readonly backup: ActivationRecordReference;
    readonly migrationManifestSha256: string;
  };
  readonly committed: {
    readonly format: 'dependency-activation-committed';
    readonly version: 1;
    readonly environment: EnvName;
    readonly receipt: DependencyActivationReceipt;
    readonly captureSha256: string;
    readonly migrationManifestSha256: string;
  };
  readonly 'participant-restore-intent': {
    readonly format: 'dependency-participant-restore-intent';
    readonly version: 1;
    readonly participants: ActivationRecordReference;
    readonly committed: readonly {
      readonly environment: EnvName;
      readonly record: ActivationRecordReference;
    }[];
    readonly solverIntent: ActivationRecordReference;
    readonly solverReady?: ActivationRecordReference;
    readonly selected: readonly {
      readonly role: DependencyParticipantRole;
      readonly id: string;
      readonly originalPolicy: ParticipantRestartPolicy;
      readonly snapshotSha256: string;
