            retained = { owner, prepared };
            expect(captures).toBe(1);
            expect(active.size).toBeGreaterThan(0);
            if (disposition === 'release')
              await consumePreparedDependencyActivation(owner, prepared);
            expired = expiry === 'expired';
            if (disposition === 'release') {
              releaseEntered = true;
