      if (!('code' in cause) || cause.code !== 'ECONNRESET') failures.push(cause);
    });
    socket.resume();
    socket.end(
      'HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 200\r\nConnection: close\r\n\r\n{"status":"ok","commit":null}',
    );
