  const directory = await mkdtemp(join(tmpdir(), 'restoration-parent-'));
  const source = new URL('../..', import.meta.url).pathname;
  try {
    for (const path of ['src/lib', 'src/fixtures', 'test'])
      await mkdir(join(directory, path), { recursive: true });
