test('Docker operation deadline rejects and aborts a non-cooperating inspection runner', async () => {
  let aborted = false;
  const start = performance.now();
  let refusal = '';
  try {
    await runDockerBefore(
      ['inspect', 'exact-id'],
      (_args, signal) =>
        new Promise(() => {
          signal?.addEventListener('abort', () => {
            aborted = true;
          });
