function localChild(program: string): {
  child: ProductMetadataChild;
  settled: () => [boolean, boolean, boolean];
} {
  const subprocess = Bun.spawn(['/usr/bin/python3', '-I', '-c', program], {
    stdin: 'ignore',
    stdout: 'pipe',
    stderr: 'pipe',
    killSignal: 'SIGKILL',
  });
