            role: 'replacement',
            id: candidate.id,
            originalId: original.id,
            phase: 'running',
          },
          networks: [{ name: 'edge', id: 'c'.repeat(64), sha256: '0'.repeat(64) }],
        }),
      ),
    ).not.toBe(expected);
  }
});

