    child,
    {
      nonce,
      coordinator,
      pids,
      daemon,
      storage,
      cgroups,
      drained: drained.map((previous) => ({ pid: previous.pid, startTime: previous.startTime })),
    },
    nonce,
    expiry,
  );
  const observed = closed(parseJson(contents), [
    'pids',
    'storage',
    'cgroups',
    'drained',
    'hostNetNamespace',
    'hostPidNamespace',
    'daemon',
  ]);
