        fields.length !== 11 ||
        !/^[a-zA-Z0-9_.-]{1,15}$/.test(fields[0] ?? '') ||
        ![1, 2, 7].every((index) => /^[a-fA-F0-9]{8}$/.test(fields[index] ?? '')) ||
        !/^[a-fA-F0-9]{4}$/.test(fields[3] ?? '') ||
        !/^[0-9]+$/.test(fields[6] ?? '')
