      if (
        fields.length !== 6 ||
        !/^[a-fA-F0-9]{32}$/.test(fields[0] ?? '') ||
        ![1, 2, 3, 4].every((index) => /^[a-fA-F0-9]+$/.test(fields[index] ?? ''))
