        refuse('registry-sockets-invalid');
      const port = Number.parseInt(local.slice(local.lastIndexOf(':') + 1), 16);
      if (ports.includes(port) && !['0A', '06', '07'].includes(state))
        refuse('registry-active-session');
    }
