  return fingerprint(
    observed
      .map((entry) => ({
        id: entry.id,
        name: entry.name,
        invariant: {
          image: entry.image,
          config: entry.config,
          host: entry.host,
          mounts: entry.mounts,
          networks: entry.networks,
        },
        state: Object.fromEntries(
          [
            'Status',
            'Running',
            'Paused',
            'Restarting',
            'Dead',
            'Pid',
            'StartedAt',
            'FinishedAt',
          ].map((key) => [key, entry.state[key]]),
        ),
        restartCount: entry.restartCount,
        networks: entry.networks,
        sandboxId: entry.sandboxId,
        sandboxKey: entry.sandboxKey,
        ports: entry.ports,
