      masked += ' ';
      if (quote === '"' && character === '\\') {
        index++;
        if (index >= line.length) refuse('compose-source-unsupported');
        masked += ' ';
      } else if (character === quote) {
        if (quote === "'" && line.charAt(index + 1) === "'") {
          index++;
