        const body = Buffer.from('PRIVATE_EXEC_SENTINEL');
        const header = Buffer.alloc(8);
        header[0] = fault === 'stderr' ? 2 : 1;
        header.writeUInt32BE(body.length + (fault === 'truncated' ? 1 : 0), 4);
