      const raw = syntheticContainer();
      raw.Id = id;
      raw.Name = `/wbs-init-synthetic-${kind}`;
      raw.Config.Image = raw.Image;
      raw.HostConfig.Init = true;
      Object.assign(raw.HostConfig, { OomKillDisable: false });
      Object.assign(raw.State, {
        Status: 'created',
