      lines[0] +
      '\n' +
      nativeLine +
      '\nFIXTURE_CLEANUP:KNOWN\n' +
      (identityLine === undefined ? '' : identityLine + '\n') +
      'CLOSE_SETTLEMENT:' +
      scenario +
      '\n';
    assert.equal(text, expected, 'UC1 closed transcript differs');
