    scenario,
    helperSHA256,
    bundleSHA256,
    executable: closeSettlementExecutable,
    pid: retained.child.pid,
    exit: termination.value,
    signal: null,
    stdout: out.value,
    stderr: err.value,
    native,
    classifications,
    original: retained,
