          const decoded: unknown = JSON.parse(line);
          const phase = readClosed(
            decoded,
            session.ready
              ? [
                  'phase',
                  'nonce',
                  'cleanup',
                  ...(typeof decoded === 'object' && decoded !== null && 'observation' in decoded
                    ? ['observation']
