const COLORS = ['blue', 'green'] as const;
const ID = /^[a-f0-9]{64}$/;
const DIGEST = /^sha256:[a-f0-9]{64}$/;

type Fields = Record<string, unknown>;
interface RestartPolicy {
  name: string;
  maximumRetryCount: number;
}
export interface ManagedState {
  running: boolean;
  paused: boolean;
  restarting: boolean;
  dead: boolean;
  oomKilled: boolean;
  pid: number;
  status: string;
  startedAt: string;
  finishedAt: string;
  exitCode: number;
  error: string;
