async function refuses(check: Promise<unknown>, message?: string): Promise<void> {
  let failure: unknown = null;
  try {
    await check;
  } catch (cause) {
    failure = cause;
  }
  expect(failure).toBeInstanceOf(Error);
  if (message !== undefined) expect(String(failure)).toContain(message);
}

