import { mkdir, readFile, writeFile } from 'node:fs/promises';

import { scratchSync } from '@tools/test-scratch';
import { expect, test } from 'bun:test';

import { envLayout } from './env';

for (const fault of ['none', 'noop', 'sync-failure', 'sibling-symlink', 'public-mode'] as const) {
  test(`actual site publication retains ordered evidence for ${fault}`, async () => {
    const root = scratchSync('owner-site-effect-');
    await writeFile(`${root}/edge.lock`, '');
    const caddy = `${root}/caddy`;
    await mkdir(caddy);
    const path = `${caddy}/site.caddy`;
    await writeFile(path, 'original secret configuration');
    const foreign = `${root}/foreign-evidence`;
    await writeFile(foreign, 'foreign retained bytes');
    const layout = { ...envLayout('prod'), root, stateDir: root, siteCaddyPath: path };
    const program = `
    import * as filesystem from 'node:fs';
    import * as relative from ${JSON.stringify(`${import.meta.dir}/directory-file.ts`)};
    import {join} from 'node:path';
    import { mock } from 'bun:test';
    const openRelative = relative.openDirectoryFile;
    const renameRelative = relative.renameDirectoryFile;
    const sync = filesystem.fsyncSync;
    const synchronized = new Set();
    const staged = new Set();
    let renamed = false;
    let observed = false;
    let directorySynced = false;
    let faultDelivered = false;
    let callbackEntered = false;
    mock.module('node:fs',()=>({...filesystem,fsyncSync:(descriptor)=>{
      if(renamed && !staged.has(descriptor)) {
        if(${JSON.stringify(fault)} === 'sync-failure'){faultDelivered=true;throw new Error('injected directory sync');}
        directorySynced=true;
      }
      sync(descriptor); synchronized.add(descriptor);
    }}));
    mock.module(${JSON.stringify(`${import.meta.dir}/directory-file.ts`)},()=>({...relative,
      openDirectoryFile:(descriptor,name,flags)=>{
        if(name.startsWith('.site.caddy.dependency-')) {
          if(${JSON.stringify(fault)} === 'sibling-symlink'){filesystem.symlinkSync(${JSON.stringify(foreign)},join(${JSON.stringify(caddy)},name));faultDelivered=true;}
          const opened=openRelative(descriptor,name,flags);
          if(${JSON.stringify(fault)} === 'public-mode'){filesystem.fchmodSync(opened,0o644);faultDelivered=true;}
          staged.add(opened);return opened;
        }
        return openRelative(descriptor,name,flags);
      },
      renameDirectoryFile:(descriptor,source,target)=>{
        const names = filesystem.readdirSync(${JSON.stringify(root)});
        const original = names.find(name=>name.endsWith('-ingress-original.json'));
        const intent = names.find(name=>name.endsWith('-ingress-intent.json'));
        if (original === undefined || intent === undefined) throw new Error('required pre-rename evidence absent');
        for (const name of [original,intent]) {
          const path=join(${JSON.stringify(root)},name);
          const contents = filesystem.readFileSync(path,'utf8');
          if (!contents.includes('original secret configuration') || (filesystem.statSync(path).mode & 0o777) !== 0o600) throw new Error('private exact original intent absent');
        }
        if (filesystem.readFileSync(${JSON.stringify(path)},'utf8') !== 'original secret configuration') throw new Error('effect preceded intent');
        if (![...staged].some(fd=>synchronized.has(fd))) throw new Error('staged file sync absent');
        if ((filesystem.statSync(join(${JSON.stringify(caddy)},source)).mode & 0o777) !== 0o600) throw new Error('native creation was not private');
        observed = true;
        if (${JSON.stringify(fault)} === 'noop') faultDelivered=true;
        if (${JSON.stringify(fault)} !== 'noop') {renameRelative(descriptor,source,target);renamed=true;}
      }
    }));
    const {withDependencyOwner,captureOwnedSiteFile,publishOwnedSiteFile} = await import(${JSON.stringify(`${import.meta.dir}/edge-ownership.ts`)});
    const layout=${JSON.stringify(layout)};
    let refused=false;
    try { await withDependencyOwner({sha:'a'.repeat(40),layouts:[layout]},async owner=>{
      callbackEntered=true;
      await publishOwnedSiteFile(owner,layout,await captureOwnedSiteFile(layout.siteCaddyPath),'maintenance');
    },${JSON.stringify(root)}); } catch(cause) {
      refused=true;
      const expected=${JSON.stringify(fault)} === 'public-mode' ? 'private creation mode differs' : ${JSON.stringify(fault)} === 'sibling-symlink' ? 'exclusive relative open failed' : ${JSON.stringify(fault)} === 'noop' ? 'readback differs' : 'injected directory sync';
      if(!String(cause).includes(expected)) throw cause;
    }
    if(!callbackEntered || (${JSON.stringify(fault)} !== 'none' && !faultDelivered)) throw new Error('intended publication fault boundary not reached');
    if(${JSON.stringify(fault)} === 'none' ? refused : !refused) throw new Error('publication refusal differs');
    if(!['sibling-symlink','public-mode'].includes(${JSON.stringify(fault)}) && !observed) throw new Error('rename effect never observed');
    if(${JSON.stringify(fault)} === 'none' && !directorySynced) throw new Error('publication directory sync absent');
  `;
    const child = Bun.spawn([process.execPath, '-e', program], { stdout: 'pipe', stderr: 'pipe' });
    const [code, stderr] = await Promise.all([child.exited, new Response(child.stderr).text()]);
    expect(stderr).toBe('');
    expect(code).toBe(0);
    expect(await readFile(path, 'utf8')).toBe(
      fault === 'noop' || fault === 'sibling-symlink' || fault === 'public-mode'
        ? 'original secret configuration'
        : 'maintenance',
    );
    expect(await readFile(foreign, 'utf8')).toBe('foreign retained bytes');
  });
}

import { createHash } from 'node:crypto';
import { join } from 'node:path';

import { assertParkedBackendFenceUnderOwner } from './backend-exclusion';
import { inspectDependencyIngress } from './dependency-ingress';
import { type RunDocker, runDockerBefore } from './docker-deadline';
import { parseDockerInspection } from './docker-inspection-json';
import {
  assertDependencyOwner,
  type DependencyOwner,
  ownerDockerHashed,
  retainSolverRecord,
} from './edge-ownership';
import { assertSame, readFields, readIdentity, readRecord } from './managed-cohort';
import { parseSolverSnapshot } from './solver-cohort';
import {
  inspectExcludedSolverMembers,
  type SolverExclusion,
  type SolverLayouts,
} from './solver-exclusion';
import {
  decodeSourceDev,
  identifyParkedSourceInventory,
  identifySourceInventory,
} from './source-dev-cohort';
import {
  assertParkedSourceDev,
  inspectExcludedSourceMember,
  type SourceDevExclusion,
} from './source-dev-exclusion';

/** Captures private monitoring state inside the final protected scope; it conveys no namespace/storage admission. */
export async function captureParkedDependencies(
  owner: DependencyOwner,
  layouts: SolverLayouts,
  sha: string,
  source: SourceDevExclusion,
  solver: SolverExclusion,
  runDocker: RunDocker,
  deadline: number,
): Promise<{
  inspect(removed: ReadonlySet<string>): Promise<void>;
  removeSolvers(): Promise<ReadonlySet<string>>;
}> {
  const docker = ownerDockerHashed(owner, layouts.prod, runDocker);
  async function assertOwner(): Promise<void> {
    await assertDependencyOwner(owner, layouts.prod, sha);
    await assertDependencyOwner(owner, layouts.dev, sha);
    if (!Number.isFinite(deadline) || performance.now() >= deadline)
      throw new Error('parked dependency observation deadline exceeded');
  }
  async function inspectInventory(): Promise<unknown[]> {
    await assertOwner();
    const stdout = await runDockerBefore(
      ['ps', '-a', '--no-trunc', '--format', '{{.ID}}'],
      docker,
      deadline,
    );
    const ids = stdout.trim() === '' ? [] : stdout.trim().split('\n').map(readIdentity);
    if (ids.length === 0 || new Set(ids).size !== ids.length)
      throw new Error('parked dependency inventory is missing or duplicate');
    const inspected = parseDockerInspection(
      await runDockerBefore(['inspect', ...ids], docker, deadline),
    );
    if (!Array.isArray(inspected))
      throw new Error('parked dependency complete inventory is malformed');
    assertSame(
      [...ids].sort(),
      inspected.map((raw) => readIdentity(readFields(raw)['Id'])).sort(),
      'parked dependency complete inventory',
    );
    await assertOwner();
    return inspected.map((raw: unknown) => raw);
  }
  const initial = await inspectInventory();
  const sourceRaw = await inspectExcludedSourceMember(owner, layouts.prod, source, initial);
  const sourceMember = decodeSourceDev(sourceRaw, layouts.dev);
  const solverRaw = await inspectExcludedSolverMembers(owner, layouts.prod, solver, initial);
  const snapshots = solverRaw.map((raw) =>
    parseSolverSnapshot(raw, readIdentity(readFields(raw)['Id'])),
  );
  const solverIds = new Set(snapshots.map((snapshot) => snapshot.solver.id));
  const nonsolver = initial.filter((raw) => !solverIds.has(readIdentity(readFields(raw)['Id'])));
  const baseline = identifySourceInventory(nonsolver, sourceRaw);
  const records = await Promise.all(
    [
      ...['intent', 'complete'].map((label) =>
        join(layouts.dev.stateDir, `dependency-source-dev-${label}.json`),
      ),
      ...['backend', 'gateway'].flatMap((role) =>
        ['fence', 'intent', 'complete'].map((label) =>
          join(layouts.prod.stateDir, `dependency-${role}-${label}.json`),
        ),
      ),
    ].map(async (path) => ({ path, contents: await readRecord(path) })),
  );
  async function inspect(removed: ReadonlySet<string>): Promise<void> {
    await assertOwner();
    for (const id of removed)
      if (!solverIds.has(id)) throw new Error('parked solver removal set is foreign');
    const current = await inspectInventory();
    await assertParkedSourceDev(owner, layouts, sha, sourceMember, current, runDocker, deadline);
    // Proof: parked-inventory omission lost the first complete-membership boundary; new-participant test failed (exit 1).
    assertSame(
      baseline,
      identifyParkedSourceInventory(
        current.filter((raw) => !solverIds.has(readIdentity(readFields(raw)['Id']))),
        layouts.dev,
        sourceMember,
      ),
      'restoration exact parked participants',
    );
    const currentIds = new Set(current.map((raw) => readIdentity(readFields(raw)['Id'])));
    for (const snapshot of snapshots) {
      const id = snapshot.solver.id;
      if (removed.has(id)) {
        // Proof: removed-attempt-absence omission accepted no-op rm; composed noop-remove test failed (exit 1).
        if (currentIds.has(id)) throw new Error('removed parked solver remains present');
      } else {
        const raw = current.find((raw) => readFields(raw)['Id'] === id);
        if (raw === undefined) throw new Error('parked solver unexpectedly missing');
        assertSame(snapshot, parseSolverSnapshot(raw, id), 'restoration exact terminal solver');
      }
    }
    for (const record of records) {
      // Proof: parked-records omission admitted changed source evidence; source-record test failed (exit 1).
      assertSame(
        record.contents,
        await readRecord(record.path),
        'restoration retained participant bytes',
      );
      await assertOwner();
    }
    await assertParkedBackendFenceUnderOwner(owner, layouts.prod, sha, runDocker, deadline, {
      layout: layouts.dev,
      member: sourceMember,
    });
    await inspectDependencyIngress(owner, [layouts.prod, layouts.dev], runDocker, deadline);
    await assertOwner();
  }
  await inspect(new Set());
  return {
    inspect,
    removeSolvers: async () => {
      const removed = new Set<string>();
      for (const snapshot of snapshots) {
        await inspect(removed);
        await retainSolverRecord(owner, layouts, 'restore-complete', {
          phase: 'terminal-attempt-removal-intent',
          id: snapshot.solver.id,
          image: snapshot.solver.image,
          snapshotSha256: createHash('sha256').update(JSON.stringify(snapshot)).digest('hex'),
        });
        await runDockerBefore(['rm', snapshot.solver.id], docker, deadline);
        removed.add(snapshot.solver.id);
        await inspect(removed);
      }
      await inspect(removed);
      return removed;
    },
  };
}

