    input,
    (value) => {
      writes.push(value);
      return Promise.resolve();
    },
    {
      maxInputBytes: overrides.maxInputBytes ?? 2 * 1024 * 1024,
      bindTimeoutMs: 5_000,
      timer: overrides.timer,
    },
  );
}

