  throw new Error('peer process proof requires Unix credentials');
const frame = {
  type: 'start',
  protocolVersion: 1,
  callerId: caller,
  projectId: '018f3f08-2ef7-7d1c-b645-14f877575d65',
  objective: 'pri',
