      format: 'source-database-bindings',
      version: 1,
      activation: 'blocked',
      prod: Object.freeze({ ...prod.database }),
      dev: Object.freeze({ ...dev.database }),
      sourceInputs,
    });
  } catch {
    return refuse();
  } finally {
    if (configuration !== undefined) {
      try {
        await configuration.close();
