function reconstructHistoricalInput(path: 'package.json' | 'bun.lock', bytes: Uint8Array): Buffer {
  expect(describeBytes(bytes)).toEqual(CAPTURED_INPUTS[path]);
  // Reverse only the exact CTT pin and resolved lock identity before older historical hunks.
  let contents = Buffer.from(bytes).toString('utf8');
  for (const [present, prior] of CURRENT_REVERSALS[path]) {
    expect(contents.split(present).length - 1).toBe(1);
    contents = contents.replace(present, prior);
  }
  expect(describeBytes(Buffer.from(contents))).toEqual(PREVIOUS_MAIN_PAIR[path]);
  // Restore the reviewed CTT pair before removing its additions. Exact hashes
  // at both boundaries keep the owned negatives independent of CI history.
  for (const [present, prior] of HISTORICAL_REVERSALS[path]) {
    expect(contents.split(present).length - 1).toBe(1);
    contents = contents.replace(present, prior);
  }
  expect(describeBytes(Buffer.from(contents))).toEqual(CTT_PAIR[path]);
  for (const hunk of HISTORICAL_REMOVALS[path]) {
    expect(contents.split(hunk).length - 1).toBe(1);
    contents = contents.replace(hunk, '');
  }
  const reconstructed = Buffer.from(contents);
  expect(describeBytes(reconstructed)).toEqual(HISTORICAL_PAIR[path]);
  return reconstructed;
}

/** Test-owned existence observation; only exact ENOENT denotes a known already-removed root. */
async function hasFrontendCleanupRoot(root: string): Promise<boolean> {
  try {
    await access(root);
    return true;
  } catch (cause) {
    if (cause instanceof Error && 'code' in cause && cause.code === 'ENOENT') return false;
    throw cause;
  }
}

async function removeFrontendTestRoot(root: string): Promise<void> {
  if (await hasFrontendCleanupRoot(root)) await rm(root, { recursive: true });
}

type FrontendCleanupOutcome =
  | { readonly kind: 'returned'; readonly value: unknown }
  | { readonly kind: 'threw'; readonly failure: unknown };

const frontendCaptureCleanupCases = [
  'success',
  'primary-only',
  'cleanup-only-missing-root',
  'both-errors',
  'undefined-primary',
  'undefined-cleanup',
] as const;
test.each([...frontendCaptureCleanupCases])(
  'frontend cleanup accounting settled capture %s',
  async (fault) => {
    const root = await mkdtemp(join(tmpdir(), 'frontend-capture-cleanup-case-'));
    const value = Object.freeze({ marker: 'same private consumer object' });
    const primary: unknown =
      fault === 'undefined-primary' ? undefined : new Error('modeled private consumer refusal');
    const cleanup: unknown =
      fault === 'undefined-cleanup' ? undefined : new Error('modeled removal dependency refusal');
    const calls: string[] = [];
    let consumeCalls = 0;
    let cleanupCalls = 0;
    const cleanupFailures: unknown[] = [];
    try {
      let outcome: FrontendCleanupOutcome;
      try {
        const returned = await consumeSourceFrontendCapture(
          async () => {
            consumeCalls++;
            calls.push('consume');
            if (fault === 'cleanup-only-missing-root') await rm(root, { recursive: true });
            if (fault !== 'success' && fault !== 'cleanup-only-missing-root') throw primary;
            return value;
          },
          async () => {
            cleanupCalls++;
            calls.push('cleanup');
            try {
              await rm(root, { recursive: true });
              // These three dependency refusals are modeled after an actual successful root removal.
              if (
                fault === 'both-errors' ||
                fault === 'undefined-primary' ||
                fault === 'undefined-cleanup'
              )
                throw cleanup;
            } catch (failure) {
              cleanupFailures.push(failure);
              throw failure;
            }
          },
        );
        outcome = { kind: 'returned', value: returned };
      } catch (failure) {
        outcome = { kind: 'threw', failure };
      }
      expect(await hasFrontendCleanupRoot(root), 'required settled capture root removal').toBe(
        false,
      );
      expect(consumeCalls, 'settled consumer invocation count').toBe(1);
      expect(cleanupCalls, 'settled removal invocation count').toBe(1);
      expect(calls).toEqual(['consume', 'cleanup']);
      if (fault === 'success') {
        expect(outcome.kind).toBe('returned');
        if (outcome.kind !== 'returned') throw new Error('settled capture unexpectedly refused');
        expect(outcome.value === value, 'same consumer value after cleanup').toBe(true);
        expect(cleanupFailures).toHaveLength(0);
      } else {
        expect(outcome.kind).toBe('threw');
        if (outcome.kind !== 'threw') throw new Error('required settled capture refusal absent');
        if (fault === 'primary-only') {
          expect(outcome.failure === primary, 'original primary-only identity').toBe(true);
          expect(cleanupFailures).toHaveLength(0);
        } else {
          expect(cleanupFailures).toHaveLength(1);
          if (fault === 'cleanup-only-missing-root') {
            expect(
              outcome.failure === cleanupFailures[0],
              'original actual missing-root rejection identity',
            ).toBe(true);
            expect(
              outcome.failure instanceof Error &&
                'code' in outcome.failure &&
                outcome.failure.code === 'ENOENT',
              'actual missing-root refusal',
            ).toBe(true);
          } else {
            expect(
              outcome.failure instanceof AggregateError,
              'both settled failures retained privately',
            ).toBe(true);
            if (!(outcome.failure instanceof AggregateError))
              throw new Error('dual settled failure aggregate absent');
            expect(
              outcome.failure.message === 'settled frontend capture and removal failed',
              'fixed private aggregate message',
            ).toBe(true);
            expect(
              outcome.failure.errors[0] === primary,
              'original primary identity retained first',
            ).toBe(true);
            expect(
              outcome.failure.errors[1] === cleanupFailures[0],
              'original cleanup identity retained second',
            ).toBe(true);
            expect(outcome.failure.errors.length).toBe(2);
          }
        }
      }
    } finally {
      await removeFrontendTestRoot(root);
    }
  },
);

const frontendPairCleanupCases = [
  'both-success',
  'first-missing',
  'second-missing',
  'both-missing',
  'no-retained-producer',
] as const;
test.each([...frontendPairCleanupCases])(
  'frontend cleanup accounting settled roots %s',
  async (fault) => {
    const provenance = await mkdtemp(join(tmpdir(), 'frontend-provenance-cleanup-case-'));
    const producer =
      fault === 'no-retained-producer'
        ? undefined
        : await mkdtemp(join(tmpdir(), 'frontend-producer-cleanup-case-'));
    const calls: { owner: FrontendRootOwner; root: string }[] = [];
    const failures = new Map<FrontendRootOwner, unknown>();
    try {
      if (fault === 'first-missing' || fault === 'both-missing')
        await rm(provenance, { recursive: true });
      if (fault === 'second-missing' || fault === 'both-missing') {
        if (producer === undefined) throw new Error('required missing-producer fixture absent');
        await rm(producer, { recursive: true });
      }
      let outcome: FrontendCleanupOutcome;
      try {
        await removeFrontendRoots(provenance, producer, async (owner, root) => {
          calls.push({ owner, root });
          try {
            await rm(root, { recursive: true });
          } catch (failure) {
            failures.set(owner, failure);
            throw failure;
          }
        });
        outcome = { kind: 'returned', value: undefined };
      } catch (failure) {
        outcome = { kind: 'threw', failure };
      }
      expect(await hasFrontendCleanupRoot(provenance), 'required provenance root removal').toBe(
        false,
      );
      if (producer !== undefined)
        expect(
          await hasFrontendCleanupRoot(producer),
          'attempt-all producer root after provenance failure',
        ).toBe(false);
      expect(calls.map((call) => call.owner)).toEqual(
        producer === undefined ? ['provenance'] : ['provenance', 'producer'],
      );
      expect(calls.at(0)?.root === provenance, 'original provenance root argument').toBe(true);
      if (producer !== undefined)
        expect(calls.at(1)?.root === producer, 'original producer root argument').toBe(true);
      if (fault === 'both-success' || fault === 'no-retained-producer') {
        expect(outcome.kind).toBe('returned');
        expect(failures.size).toBe(0);
      } else {
        expect(outcome.kind).toBe('threw');
        if (outcome.kind !== 'threw') throw new Error('required root-removal refusal absent');
        if (fault === 'both-missing') {
          expect(failures.has('provenance')).toBe(true);
          expect(failures.has('producer')).toBe(true);
          expect(
            outcome.failure instanceof AggregateError,
            'both original root failures retained',
          ).toBe(true);
          if (!(outcome.failure instanceof AggregateError))
            throw new Error('dual root-removal aggregate absent');
          expect(
            outcome.failure.message === 'frontend owned root removals failed',
            'fixed private root aggregate message',
          ).toBe(true);
          expect(outcome.failure.errors.length).toBe(2);
          expect(
            outcome.failure.errors[0] === failures.get('provenance'),
            'first original removal identity',
          ).toBe(true);
          expect(
            outcome.failure.errors[1] === failures.get('producer'),
            'second original removal identity',
          ).toBe(true);
        } else {
          const owner = fault === 'first-missing' ? 'provenance' : 'producer';
          expect(failures.size).toBe(1);
          expect(failures.has(owner)).toBe(true);
          expect(
            outcome.failure === failures.get(owner),
            'single original removal failure identity',
          ).toBe(true);
        }
      }
    } finally {
      await removeFrontendTestRoot(provenance);
      if (producer !== undefined) await removeFrontendTestRoot(producer);
    }
  },
);

import { createHash } from 'node:crypto';

import type { ParticipantHttpObservation } from './dependency-participant-health';

const DOCUMENT_SHA256 = '09ab3b528f1a147d34addea248fa08925801d66ee9f384bb634112b9abc30e2f';
const ENTRY_SHA256 = 'e990c7ae6b545d4177b27560878bd41d34843b32109a21af190794d73e45ee08';

function inspectEnvelope(observation: ParticipantHttpObservation, contentType: RegExp): void {
  // Proof: separate status and MIME omissions admitted exact-body unsupported envelopes; their owning negatives failed, then passed after restoration.
  if (observation.status !== 200 || !contentType.test(observation.contentType))
    throw new Error('source frontend HTTP envelope unsupported');
}
const digest = (body: string) => createHash('sha256').update(body).digest('hex');

/**
 * Recognizes only the complete reviewed Vite document transported text, including its client
 * insertion and theme bootstrap. The HTTP reader's fatal UTF-8 text boundary can remove a BOM;
 * this digest identifies its UTF-8 encoding, not universal raw wire bytes. Requires 200
 * text/html (optional parameters); unsupported status, MIME or complete text throws. No normalization or
 * browser execution occurs. This evidence alone grants no readiness or source-profile authority.
 */
export function inspectSourceFrontendDocument(observation: ParticipantHttpObservation): {
  readonly sha256: string;
} {
  inspectEnvelope(observation, /^text\/html(?:\s*;|$)/i);
  const sha256 = digest(observation.body);
  // Proof: omitting complete text equality admitted an injected-script actual HTTP response; the document refusal failed, then passed after restoration.
  if (sha256 !== DOCUMENT_SHA256) throw new Error('source frontend document unsupported');
  return { sha256 };
}

/**
 * Recognizes the complete reviewed entry transported text, including executable code and the
 * entire trailing inline map. Correct sourcesContent alone cannot authenticate executable text.
 * Requires 200 text/javascript (optional parameters); unsupported status, MIME or complete
 * text throws. No JavaScript is evaluated; this evidence does not establish browser bootstrap or readiness.
 */
export function inspectSourceFrontendEntry(observation: ParticipantHttpObservation): {
  readonly sha256: string;
} {
  inspectEnvelope(observation, /^text\/javascript(?:\s*;|$)/i);
  const sha256 = digest(observation.body);
  // Proof: omitting complete text equality independently admitted changed executable and changed-map HTTP responses; both refusals failed, then passed after restoration.
  if (sha256 !== ENTRY_SHA256) throw new Error('source frontend entry unsupported');
  return { sha256 };
}

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';

import { expect, test } from 'bun:test';
import ts from 'typescript';

import { SOURCE_FRONTEND_PRODUCER_PROGRAM } from '../fixtures/source-frontend-producer-program';

type Probe = (bindings: Record<string, unknown>) => Promise<unknown>;
type ProbeSettlement =
  { status: 'fulfilled'; capture: unknown } | { status: 'rejected'; failure: unknown };

async function settleProbe(
  probe: Probe,
  bindings: Record<string, unknown>,
): Promise<ProbeSettlement> {
  try {
    return { status: 'fulfilled', capture: await probe(bindings) };
  } catch (failure) {
    return { status: 'rejected', failure };
  }
}

/** Extracts the real producer's package/idle tail, catch, and cleanup from its JavaScript AST. */
function extractProbe(): Probe {
  const source = ts.createSourceFile(
    'probe.mjs',
    SOURCE_FRONTEND_PRODUCER_PROGRAM,
    ts.ScriptTarget.Latest,
    true,
    ts.ScriptKind.JS,
  );
  const lifecycle = source.statements.find(ts.isTryStatement);
  assert.ok(lifecycle?.catchClause !== undefined);
  assert.ok(lifecycle.finallyBlock !== undefined);
  const start = lifecycle.tryBlock.statements.findIndex(
    (statement) => statement.getText(source) === "phase = 'package-observations';",
  );
  assert.ok(start >= 0);
  const tail = lifecycle.tryBlock.statements
    .slice(start)
    .map((statement) => statement.getText(source))
    .join('\n');
  const terminal = source.statements.at(-1);
  assert.ok(terminal !== undefined && ts.isIfStatement(terminal));
  const lifecycleSource = `try { ${tail} } ${lifecycle.catchClause.getText(source)} finally ${lifecycle.finallyBlock.getText(source)}\n${terminal.getText(source)} return capture;`;
  const prototype: unknown = Object.getPrototypeOf(settleProbe);
  assert.ok(typeof prototype === 'object' && prototype !== null);
  const constructor: unknown = Reflect.get(prototype, 'constructor');
  assert.ok(typeof constructor === 'function');
  // Trusted generated probe source is the only constructor input in this inert test.
  return Reflect.construct(constructor, [
    'bindings',
    `with (bindings) { ${lifecycleSource} }`,
  ]) as Probe;
}

function createFixture() {
  const events: string[] = [];
  const idle = Promise.withResolvers<undefined>();
  const firstBoundary = Promise.withResolvers<'idle' | 'close'>();
  const watcher = {
    closed: false,
    close() {
      events.push('watcher-close');
      this.closed = true;
      return Promise.resolve();
    },
    getWatched: () => ({}),
  };
  const server = {
    watcher,
    httpServer: { listening: false },
    waitForRequestsIdle() {
      events.push('idle-entered');
      firstBoundary.resolve('idle');
      return idle.promise;
    },
    close() {
      events.push('close-entered');
      firstBoundary.resolve('close');
      watcher.closed = true;
      return Promise.resolve();
    },
  };
  const capture: Record<string, unknown> = {
    responses: [{}, {}],
    requestAudit: [{}, {}],
    cleanup: {},
  };
  const bindings = {
    assert,
    capture,
    console: { log: () => undefined },
    digest: (bytes: Uint8Array) => createHash('sha256').update(bytes).digest('hex'),
    failure: undefined,
    packet: '/inert',
    phase: 'entry',
    publishPreCleanupDiagnostic: () => ({ status: 'written' }),
    observeCloseBoundaries: () => events.push('observe-close'),
    readFile: () => Promise.resolve(Buffer.from('{"version":"inert"}')),
    realpath: (path: string) => Promise.resolve(path),
    resolve,
    server,
    snapshot: '/inert/snapshot',
    writeFile: () => {
      events.push('observation-written');
      return Promise.resolve();
    },
  };
  return { bindings, capture, events, idle, firstBoundary: firstBoundary.promise };
}

test('generated producer awaits idle before cleanup without losing capture', async () => {
  const fixture = createFixture();
  const settled = settleProbe(extractProbe(), fixture.bindings);
  try {
    expect(await fixture.firstBoundary).toBe('idle');
    expect(fixture.events).toEqual(['idle-entered']);
    fixture.idle.resolve(undefined);
    expect(await settled).toEqual({ status: 'fulfilled', capture: fixture.capture });
  } finally {
    fixture.idle.resolve(undefined);
    await settled;
  }
  expect(fixture.events).toEqual([
    'idle-entered',
    'observe-close',
    'close-entered',
    'watcher-close',
    'observation-written',
  ]);
  expect((fixture.capture['cleanup'] as Record<string, unknown>)['closeReturned']).toBe(true);
  expect(fixture.capture['responses']).toHaveLength(2);
}, 5000);

test('generated producer preserves idle refusal and still proves cleanup', async () => {
  const fixture = createFixture();
  const refusal = new Error('inert idle refusal');
  const settled = settleProbe(extractProbe(), fixture.bindings);
  try {
    expect(await fixture.firstBoundary).toBe('idle');
    expect(fixture.events).toEqual(['idle-entered']);
    fixture.idle.reject(refusal);
    const outcome = await settled;
    if (outcome.status !== 'rejected') throw new Error('inert idle refusal was swallowed');
    expect(outcome.failure).toBe(refusal);
  } finally {
    fixture.idle.resolve(undefined);
    await settled;
  }
  expect(fixture.events).toEqual([
    'idle-entered',
    'observe-close',
    'close-entered',
    'watcher-close',
    'observation-written',
  ]);
  expect((fixture.capture['cleanup'] as Record<string, unknown>)['closeReturned']).toBe(true);
  expect(fixture.capture['responses']).toHaveLength(2);
}, 5000);

