import { afterEach, expect, test } from 'bun:test';

import { assertNoWriterBarrier, clearWriterBarrier, writeWriterBarrier } from './writer-barrier';

const roots: string[] = [];
afterEach(async () => {
  for (const root of roots.splice(0)) await rm(root, { recursive: true });
});
async function stateRoot(): Promise<string> {
  const root = await mkdtemp(join(tmpdir(), 'writer-barrier-'));
  roots.push(root);
  return root;
}
const intent = {
  candidate: 'registry/be@sha256:abc',
  sha: 'deadbeef',
  from: 'blue' as const,
  to: 'green' as const,
  outgoingId: 'a'.repeat(64),
  rollback: {
    containerId: 'a'.repeat(64),
    image: 'registry/be@sha256:abc',
    imageId: `sha256:${'b'.repeat(64)}`,
  },
};

test('persisted stop intent blocks an ordinary retry without replacing recovery bytes', async () => {
  const root = await stateRoot();
  await assertNoWriterBarrier(root);
  await writeWriterBarrier(root, 'stop', intent);
  const before = await readFile(join(root, 'be-writer-stop.json'), 'utf8');
  await refuses(assertNoWriterBarrier(root), 'explicit recovery');
  await refuses(writeWriterBarrier(root, 'stop', { ...intent, sha: 'other' }));
  expect(await readFile(join(root, 'be-writer-stop.json'), 'utf8')).toBe(before);
});

test('a malformed or unreadable marker never admits an ordinary retry', async () => {
  const root = await stateRoot();
  await writeFile(join(root, 'be-writer-exposure.json'), 'broken');
  await refuses(assertNoWriterBarrier(root), 'explicit recovery');
  await refuses(assertNoWriterBarrier(join(root, 'be-writer-exposure.json')));
});

test('commit removes both persisted barriers before a subsequent deploy', async () => {
  const root = await stateRoot();
  await writeWriterBarrier(root, 'stop', intent);
  await writeWriterBarrier(root, 'exposure', intent);
  await clearWriterBarrier(root);
  await assertNoWriterBarrier(root);
});

async function refuses(operation: Promise<unknown>, text?: string): Promise<void> {
  let failure = '';
  try {
    await operation;
  } catch (cause) {
    failure = cause instanceof Error ? cause.message : String(cause);
  }
  expect(failure).not.toBe('');
  if (text !== undefined) expect(failure).toContain(text);
}

test('an absent trusted state directory cannot mean no interrupted transition', async () => {
  const root = await stateRoot();
  await refuses(assertNoWriterBarrier(join(root, 'missing')));
});

import { open, readFile, stat, unlink } from 'node:fs/promises';

import type { BackendSnapshot } from './backend-maintenance';
import { writeNewMigrationCapture } from './migration-capture-file';
import type { Color } from './state';

/** Immutable outgoing image bound to the exact container observed before writer stop. */
export interface WriterImage {
  containerId: string;
  image: string;
  imageId: string;
}

/** Durable recovery identity, captured before the outgoing writer is stopped. */
export interface WriterIntent {
  candidate: string;
  sha: string;
  from: Color | null;
  to: Color;
  outgoingId: string | null;
  /** Null denotes a proven first installation with no outgoing writer. */
  rollback: WriterImage | null;
  databaseHostPath?: string;
  idleId?: string | null;
  snapshots?: { imageId: string; application: BackendSnapshot; maintenance: BackendSnapshot };
  maintenance?: {
    identity: string;
    imageId: string;
    application: BackendSnapshot;
    maintenance: BackendSnapshot;
  };
  capture?: { path: string; sha256: string; databasePath: string; target: string; attempt: string };
}

// Proof: omitting activation let its exact durable intent pass ordinary retry admission.
const boundaries = ['stop', 'exposure', 'migration', 'maintenance', 'activation'] as const;
function markerPath(root: string, boundary: (typeof boundaries)[number]): string {
  return `${root}/be-writer-${boundary}.json`;
}

/** Any retained boundary requires attended recovery, including malformed bytes. */
export async function assertNoWriterBarrier(root: string): Promise<void> {
  // Proof: omitting the directory check admitted an absent trusted state root;
  // `an absent trusted state directory cannot mean no interrupted transition` failed.
  if (!(await stat(root)).isDirectory()) throw new Error('writer state root is not a directory');
  for (const boundary of boundaries) {
    const path = markerPath(root, boundary);
    try {
      await readFile(path);
    } catch (cause) {
      // Only an absent marker is a clean transition; unreadable trusted state refuses.
      if (cause instanceof Error && 'code' in cause && cause.code === 'ENOENT') continue;
      throw new Error(`cannot inspect writer barrier ${path}; explicit recovery required`, {
        cause,
      });
    }
    // Proof: removing this refusal admitted the malformed exposure marker in
    // `a malformed or unreadable marker never admits an ordinary retry`.
    throw new Error(`retained writer barrier ${path}; explicit recovery required`);
  }
}

/** Exclusively publishes and syncs intent before either destructive or exposing IO. */
export async function writeWriterBarrier(
  root: string,
  boundary: Exclude<(typeof boundaries)[number], 'activation'>,
  intent: WriterIntent,
): Promise<void> {
  await writeNewMigrationCapture(markerPath(root, boundary), `${JSON.stringify(intent)}\n`);
}

/** Called only after the recorded candidate commit; directory sync makes removal durable. */
export async function clearWriterBarrier(
  root: string,
  hasMigration = false,
  hasMaintenance = false,
  hasActivation = false,
): Promise<void> {
  for (const boundary of boundaries) {
    if (boundary === 'migration' && !hasMigration) continue;
    if (boundary === 'maintenance' && !hasMaintenance) continue;
    if (boundary === 'activation' && !hasActivation) continue;
    await unlink(markerPath(root, boundary));
  }
  const directory = await open(root, 'r');
  try {
    await directory.sync();
  } finally {
    await directory.close();
  }
}

