/** Returns verified receipts only after the fixed authority and each reverse byte comparison pass. */
export function applyCoupledOverlay(
  baseMap: ReadonlyMap<string, Uint8Array>,
  rawPatch: Uint8Array,
  rawManifest: Uint8Array,
): {
