    const reversals: { position: number; before: string; after: string }[] = [];
    const cuts =
      role.mode === 'transform' ? [...ordinaryHoldConcreteCutsV1(role.relative, root)] : [];
    if (role.relative.endsWith('/edge-ownership.ts')) {
