  return value as Record<string, unknown>;
}
function ordinaryHoldSha(value: unknown, subject: string): string {
  if (typeof value !== 'string' || !/^[a-f0-9]{64}$/.test(value))
    throw new Error(`${subject} SHA-256 differs`);
