  if (
    typeof path !== 'string' ||
    !path.startsWith('/') ||
    path === '/' ||
    path.includes('\0') ||
    path.endsWith('/') ||
    path.includes('//') ||
    path.split('/').some((part) => part === '.' || part === '..')
