function decodeOrdinaryCompilerClosureV1(value: unknown, policy: OrdinaryCompilerPolicyV1) {
  const packet = ordinaryHoldFields(
    value,
    [
      'format',
      'version',
      'sourceEpoch',
      'sourceRoot',
      'sourceRootCanonical',
      'compilerCwd',
      'readLeaseAssumption',
      'files',
      'directories',
      'symlinks',
      'absences',
      'compilerInputs',
      'virtualInputs',
      'generatedEntry',
      'historicalSourcePins',
      'census',
      'closureOperationCount',
    ],
