    () => {
      settlement.outcome = { phase: 'fulfilled' };
      drainPreparationCleanup(record);
      maybeReleaseComposition(record);
    },
    (cause: unknown) => {
      settlement.outcome = { phase: 'rejected', cause };
      record.failures.push({ boundary: 'operation', cause });
      drainPreparationCleanup(record);
      maybeReleaseComposition(record);
