    preparation: record,
    kind,
    original: undefined,
    observer: undefined,
    outcome: { phase: 'starting' },
  };
  const operation: PreparationOperation = Object.freeze({ [operationIdentity]: true as const });
  operations.set(operation, operationRecord);
  record.operations.add(operationRecord);
  return operation;
}
