function decodeSnapshot(value: unknown, path: string): EdgeRecordSnapshot {
  const fields = readClosed(value, [
    'path',
    'device',
    'inode',
    'parentDevice',
    'parentInode',
    'mode',
    'contents',
  ]);
  const contents = readContents(fields['contents'], 65536);
