    refuseGraph('planned snapshot path or mode differs');
  return {
    path,
    contents,
    mode: 384,
    device: readDecimal(fields['device']),
    inode: readDecimal(fields['inode']),
    parentDevice: readDecimal(fields['parentDevice']),
    parentInode: readDecimal(fields['parentInode']),
