  const restoredCapture = captureReference(
    context,
    restoredRef,
    'activation-participants-restored',
    intentRef.name,
  );
  const restored = decodeRecord(restoredCapture.fields, 'dependency-participants-restored', [
    'restoration',
    'activated',
    'ready',
    'policies',
