    const intentCapture = captureReference(
      context,
      selection.intent,
      'activation-intent',
      intentRef.name,
    );
    const activationIntent = decodeRecord(intentCapture.fields, 'dependency-activation-intent', [
      'environment',
      'receipt',
      'participantRecord',
      'capture',
      'backup',
      'migrationManifestSha256',
    ]);
