type CompleteActivationArguments = [
  owner: DependencyOwner,
  request: CompleteDependencyActivationRequest,
  layouts: SolverLayouts,
  deadline: number,
  directory: string,
  ports: CompleteActivationTransports,
];
type CompleteActivationPacket = Awaited<ReturnType<typeof activateCompleteBody>>;
function activateCompleteUnderOwner(
  args: CompleteActivationArguments,
  purpose: 'fenced',
): Promise<CompleteDependencyActivationCompletion>;
function activateCompleteUnderOwner(
  args: CompleteActivationArguments,
  purpose: 'restoration' | 'initial-handoff',
): Promise<PreparedDependencyActivation>;
/** Synchronously reserves the real composition before its private body can acquire anything. */
function activateCompleteUnderOwner(
  args: CompleteActivationArguments,
  purpose: 'fenced' | 'restoration' | 'initial-handoff',
): Promise<CompleteDependencyActivationCompletion | PreparedDependencyActivation> {
  try {
    const preparation = enrollDependencyPreparation(args[0], {
      layouts: [args[2].prod, args[2].dev],
      deadline: args[3],
      purpose,
    });
    const body = bindPreparationComposition(
      preparation,
      activateCompleteBody(...args, purpose, preparation),
    );
    if (purpose === 'fenced')
      return bindPreparationProjection(preparation, projectFencedCompletion(preparation, body));
    return bindPreparationProjection(preparation, projectPreparedCompletion(preparation, body));
  } catch (cause) {
    return Promise.reject(cause);
  }
}
async function projectFencedCompletion(
  preparation: DependencyPreparation,
  body: Promise<CompleteActivationPacket>,
): Promise<CompleteDependencyActivationCompletion> {
  await Promise.allSettled([body]);
  await assertPreparationCompletion(preparation);
  return (await body).completion;
}
async function projectPreparedCompletion(
  preparation: DependencyPreparation,
  body: Promise<CompleteActivationPacket>,
): Promise<PreparedDependencyActivation> {
  await Promise.allSettled([body]);
  await assertPreparationCompletion(preparation);
  const packet = await body;
  if (packet.prepared === undefined) throw new Error('finalized activation preparation absent');
  return packet.prepared;
}
/** Frozen fenced-only composition. It never retains a participant restoration grant or starts participants. */
export function activateCompleteDependenciesUnderOwner(
  ...args: CompleteActivationArguments
): Promise<CompleteDependencyActivationCompletion> {
  return activateCompleteUnderOwner(args, 'fenced');
}
/** Internal same-owner activation path; only actual post-finalizer success mints this opaque original object. */
export function prepareActivatedParticipantsUnderOwner(
  ...args: CompleteActivationArguments
): Promise<PreparedDependencyActivation> {
  return activateCompleteUnderOwner(args, 'restoration');
}
/** Fixed full-preparation profile sharing original owner, scope and one-shot identity maps. */
export function prepareInitialDependencyHandoffUnderOwner(
  ...args: CompleteActivationArguments
): Promise<PreparedDependencyActivation> {
  try {
    const request = structuredClone(args[1]);
    function freeze(value: unknown): void {
      if (typeof value !== 'object' || value === null) return;
      for (const child of Object.values(value)) freeze(child);
      Object.freeze(value);
    }
    freeze(request);
    return activateCompleteUnderOwner(
      [args[0], request, args[2], args[3], args[4], args[5]],
      'initial-handoff',
    );
  } catch (cause) {
    return Promise.reject(cause);
  }
}
/** Consumes the original finalized object once, before any restart effect. Owner expiry cannot be replaced with historical records. */
export function consumePreparedDependencyActivation(
  owner: DependencyOwner,
  prepared: PreparedDependencyActivation,
): Promise<FinalizedParticipantRestorationContext> {
  let retained:
    | {
        readonly context: FinalizedParticipantRestorationContext;
        readonly preparation: DependencyPreparation;
      }
    | undefined;
  try {
    const association = preparations.get(prepared);
    if (association?.context.owner !== owner || consumedPreparations.has(prepared))
      throw new Error('participant restoration preparation is not live and unused');
    retained = association;
    assertPreparedContextAssociation(retained.preparation, prepared, retained.context);
    const operation = beginPreparationOperation(retained.preparation, 'preparation-consume');
    return bindPreparationOperation(
      operation,
      consumePreparation(owner, prepared, retained.context, retained.preparation, operation),
    );
  } catch (cause) {
    if (retained === undefined) return Promise.reject(cause);
    const { context, preparation } = retained;
    recordPreparationFailure(preparation, 'consume', cause);
    preparations.delete(prepared);
    preparedContexts.delete(context);
    requestPreparationClose(preparation, 'consume');
    return Promise.reject(
      refuseActivation(
        context.attempt,
        'restoration-consume',
        new Map(context.storage.receipts.map(({ environment, receipt }) => [environment, receipt])),
        [cause],
      ),
    );
  }
}
async function consumePreparation(
  owner: DependencyOwner,
  prepared: PreparedDependencyActivation,
  context: FinalizedParticipantRestorationContext,
  preparation: DependencyPreparation,
  operation: PreparationOperation,
): Promise<FinalizedParticipantRestorationContext> {
  try {
    assertPreparationOperation(operation);
    consumedPreparations.add(prepared);
    markPreparationConsumed(preparation, prepared, context);
    if (!Number.isFinite(context.deadline) || performance.now() >= context.deadline)
      throw new Error('participant restoration deadline exceeded');
    await assertDependencyOwner(owner, context.layouts.prod, context.request.owner.sha);
    assertPreparationOperation(operation);
    await assertDependencyOwner(owner, context.layouts.dev, context.request.owner.sha);
    assertPreparationOperation(operation);
    assertSame(
      context.pending,
      await captureEdgeRecord(context.directory, 'edge-owner.pending', 65536),
      'restoration original pending ownership',
    );
    assertPreparationOperation(operation);
    assertSame(
      context.fencedComplete,
      await captureEdgeRecord(context.directory, basename(context.fencedComplete.path), 65536),
      'restoration finalized fence',
    );
    assertPreparationOperation(operation);
    await context.storage.evidence.inspect();
    assertPreparationOperation(operation);
    context.artifact.verify();
    await context.storage.stores.inspect();
    assertPreparationOperation(operation);
    await context.source.inspectCold();
    assertPreparationOperation(operation);
    await context.storage.evidence.inspect();
    assertPreparationOperation(operation);
    if (performance.now() >= context.deadline)
      throw new Error('participant restoration deadline exceeded');
    assertPreparationOperation(operation);
    return context;
  } catch (cause) {
    recordPreparationFailure(preparation, 'consume', cause);
    preparations.delete(prepared);
    preparedContexts.delete(context);
    requestPreparationClose(preparation, 'consume');
    throw refuseActivation(
      context.attempt,
      'restoration-consume',
      new Map(context.storage.receipts.map(({ environment, receipt }) => [environment, receipt])),
      [cause],
    );
