      fields['environment'] !== expected[0] ||
      fields['name'] !== expected[1]
    )
      refuseGraph('planned fence roster differs');
    return {
      environment: expected[0],
      name: expected[1],
      snapshot: decodeSnapshot(
        fields['snapshot'],
        join(envLayout(expected[0]).stateDir, expected[1]),
      ),
    };
  });
