function canonicalMetadataIdentity(root,cwd,entry,label){
 // Proof: foreign-cwd absolute scanner was admitted with this guard removed; inert independent-controls.json records reject/admit/reject.
 assert.equal(cwd,root,'compiler cwd differs');
 assert.equal(typeof label,'string');assert(label.length>0,'empty metadata identity');
 if(label.startsWith('ordinary-hold-v1:')||label.startsWith('node:')||label==='bun:sqlite')return label;
 const absolute=resolve(cwd,label);
 return absolute===entry?'generated:ordinary-image-entry.ts':absolute;
}
function reconstructAssociations(coverage,closure,contract,cwd,entry,rawEdges){
 const root=coverage.sourceRoot;
 assert.equal(contract.authority.sha256,'310ec432d8d6e83a2609e7a816766d1d7f2a0fa9d294a13971430f8faf430fdd');
 assert.equal(contract.rows.length,27);assert.equal(contract.importers.length,5);
 const sealedRows=new Map(coverage.rows.map(row=>[row.identity,row]));assert.equal(sealedRows.size,coverage.rows.length);
 const closed=new Map();
 for(const pin of contract.importers){
  const identity=root+'/'+pin.relativeImporter,source=sealedRows.get(identity),physical=closure.files.find(row=>row.canonical===identity);
  assert(source!==undefined&&physical!==undefined,'historical importer absent');
  assert.equal(source.mode,'default');assert.equal(physical.compilerMode,'default');
  // Proof: altered coverage and physical importer hashes passed their respective omitted comparisons; both restored negatives refuse.
  for(const field of ['bytes','sha256']){assert.equal(source[field],pin[field],'historical sealed importer pin differs');assert.equal(physical[field],pin[field],'historical physical importer pin differs');}
 }
 for(const pin of contract.rows){
  const key=JSON.stringify([root+'/'+pin.relativeImporter,pin.rawPath]);assert(!closed.has(key),'historical tuple repeated');closed.set(key,pin);
 }
 return rawEdges.map(raw=>{
  assert.equal(typeof raw.kind,'string');
  const originalPresent=Object.hasOwn(raw,'original');
  if(originalPresent)assert.equal(typeof raw.original,'string','present original must be text');
  if(Object.hasOwn(raw,'external'))assert.equal(typeof raw.external,'boolean','external must be boolean');
  const importerIdentity=canonicalMetadataIdentity(root,cwd,entry,raw.rawImporter),source=sealedRows.get(importerIdentity);
  assert(source!==undefined,'metadata importer unsealed');
  const directIdentity=raw.external===true&&!raw.rawPath.startsWith('/')?raw.rawPath:canonicalMetadataIdentity(root,cwd,entry,raw.rawPath);
  const alternatives=[];
  for(const sealed of source.imports){
   // Proof: forged direct original, changed direct/scanner flag, forged node path and inserted historical original passed only their omitted comparisons; independent-controls.json records restoration.
   if(sealed.from!==importerIdentity||sealed.kind!==raw.kind||(originalPresent&&sealed.specifier!==raw.original))continue;
   if(directIdentity===sealed.destination&&(raw.external===true)===sealed.external)alternatives.push({sealed,representation:'direct'});
   if(raw.external===true&&originalPresent&&raw.original.startsWith('node:')&&sealed.external===true&&sealed.destination===raw.original&&sealed.specifier===raw.original&&raw.rawPath===raw.original.slice(5))alternatives.push({sealed,representation:'node-prefix'});
   const pin=closed.get(JSON.stringify([importerIdentity,raw.rawPath]));
   if(pin!==undefined&&raw.external===true&&!originalPresent&&raw.kind==='import-statement'&&sealed.external===false&&sealed.rule==='default-bun-resolveSync'&&sealed.specifier===raw.rawPath&&sealed.destination===root+'/'+pin.relativeDestination&&resolve(dirname(importerIdentity),raw.rawPath)===sealed.destination&&sealedRows.has(sealed.destination))alternatives.push({sealed,representation:'historical-relative'});
  }
  const unique=new Map(alternatives.map(choice=>[JSON.stringify([choice.sealed.destination,choice.sealed.specifier,choice.sealed.external,choice.representation]),choice]));
  // Proof: a second incompatible semantic association passed when exact cardinality was replaced with nonempty; restored negative refuses.
  assert.equal(unique.size,1,'metadata association absent or ambiguous');
  const {sealed,representation}=unique.values().next().value;
  return {...raw,originalPresent,importerIdentity,identity:sealed.destination,sourceExternal:sealed.external,sealedSpecifier:sealed.specifier,representation};
 });
}
function rawMetafileEdges(metafile){
 return Object.entries(metafile.inputs).flatMap(([rawImporter,row])=>row.imports.map(edge=>({rawImporter,rawPath:edge.path,kind:edge.kind,...(Object.hasOwn(edge,'external')?{external:edge.external}:{}),...(Object.hasOwn(edge,'original')?{original:edge.original}:{})})));
}
